    def _resolve_extra_activation_from_hand(self, state: GameState, pending: PendingAction, *, negated: bool) -> None:
        player = state.players[pending.actor_player_id]
        target_id = int(pending.payload.get("card_instance_id") or -1)
        # By rule timing, the Extra card is already in Drop when counter timing occurs.
        exists_in_drop = any(c.instance_id == target_id for c in player.drop)
        if not exists_in_drop:
            return
        if negated:
            self._checkpoint(state, "extra_activation_negated")
        else:
            source = next((c for c in player.drop if c.instance_id == target_id), None)
            if source is None:
                return
            selected_effect_id = int(pending.payload.get("selected_effect_id") or -1)
            selected_effect = next(
                (
                    reg
                    for reg in state.effect_registry
                    if reg.source_instance_id == source.instance_id
                    and reg.source_zone == "drop"
                    and reg.trigger == "self_activate_extra_from_hand"
                    and (selected_effect_id <= 0 or reg.effect_id == selected_effect_id)
                ),
                None,
            )
            discard_before = (
                self._resolve_effect_int_param(state, selected_effect, "discard_from_hand_before", default=0)
                if selected_effect is not None
                else 0
            )
            if discard_before > 0:
                if len(player.hand) < discard_before:
                    self._checkpoint(state, "extra_activation_failed_selected_effect_cost")
                    return
                for _ in range(discard_before):
                    player.drop.append(player.hand.pop(0))
            if not self._can_pay_skill_cost(player, source, "activate_extra_from_hand"):
                self._checkpoint(state, "extra_activation_failed_skill_cost")
                return
            self._pay_skill_cost(state, player, source, "activate_extra_from_hand")
            self._emit_effect_event(
                state,
                name="skill_activated",
                actor_player_id=pending.actor_player_id,
                payload={
                    "source_zone": "drop",
                    "source_index": -1,
                    "source_instance_id": int(source.instance_id),
                    "source_card_id": int(source.card_id),
                    "skill_kind": "activate_extra_from_hand",
                    "selected_effect_id": selected_effect_id if selected_effect_id > 0 else None,
                },
            )
            matching_registered_effect = any(
                reg.source_instance_id == source.instance_id
                and reg.trigger == "self_activate_extra_from_hand"
                and (selected_effect_id <= 0 or reg.effect_id == selected_effect_id)
                for reg in state.effect_registry
            )
            if not matching_registered_effect:
                state.log.append(
                    f"Unsupported skill activation: source_card_id={int(source.card_id)} kind=activate_extra_from_hand"
                )
                self._checkpoint(state, "skill_activation_no_registered_effect")
            if any(str(k).strip().lower() == "field" for k in (source.keywords or ())):
                self._emit_effect_event(
                    state,
                    name="field_extra_placed",
                    actor_player_id=pending.actor_player_id,
                    payload={
                        "source_instance_id": source.instance_id,
                        "source_card_id": source.card_id,
                    },
                )
            self._checkpoint(state, "extra_activation_resolved")

    def _resolve_zone_card(self, state: GameState, *, player_id: int, zone: str, index: int | None) -> CardInstance:
        player = state.players[player_id]
        if zone == "leader":
            return player.leader_area
        if zone == "hand":
            if index is None or not (0 <= index < len(player.hand)):
                raise RulesViolation("Invalid hand index.")
            return player.hand[index]
        if zone == "battle":
            if index is None or not (0 <= index < len(player.battle_area)):
                raise RulesViolation("Invalid battle index.")
            return player.battle_area[index]
        if zone == "unison":
            if index is None or not (0 <= index < len(player.unison_area)):
                raise RulesViolation("Invalid unison index.")
            return player.unison_area[index]
        if zone == "combo":
            if index is None or not (0 <= index < len(player.combo_area)):
                raise RulesViolation("Invalid combo index.")
            return player.combo_area[index]
        if zone == "drop":
            if index is None or not (0 <= index < len(player.drop)):
                raise RulesViolation("Invalid drop index.")
            return player.drop[index]
        raise RulesViolation(f"Unsupported zone: {zone}")

    def _find_by_instance(self, player: PlayerState, zone: str, instance_id: int) -> CardInstance | None:
        if zone == "leader":
            return player.leader_area if player.leader_area.instance_id == instance_id else None
        zone_cards = (
            player.hand
            if zone == "hand"
            else player.life
            if zone == "life"
            else player.energy
            if zone == "energy"
            else player.z_energy
            if zone == "z_energy"
            else player.battle_area
            if zone == "battle"
            else player.unison_area
            if zone == "unison"
            else player.combo_area
            if zone == "combo"
            else player.drop
            if zone == "drop"
            else player.warp
            if zone == "warp"
            else []
        )
        for c in zone_cards:
            if c.instance_id == instance_id:
                return c
        return None

    def _find_card_anywhere_by_instance(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        instance_id: int,
    ) -> tuple[str, CardInstance] | None:
        player = state.players.get(owner_player_id)
        if player is None:
            return None
        if player.leader_area.instance_id == instance_id:
            return ("leader", player.leader_area)
        zones: list[tuple[str, list[CardInstance]]] = [
            ("hand", player.hand),
            ("life", player.life),
            ("energy", player.energy),
            ("z_energy", player.z_energy),
            ("battle", player.battle_area),
            ("unison", player.unison_area),
            ("combo", player.combo_area),
            ("drop", player.drop),
            ("warp", player.warp),
            ("removed_from_game", player.removed_from_game),
        ]
        for zone_name, zone_cards in zones:
            for card in zone_cards:
                if card.instance_id == instance_id:
                    return (zone_name, card)
        return None

    def _find_board_card_by_instance(self, player: PlayerState, instance_id: int) -> CardInstance | None:
        for card in player.battle_area:
            if card.instance_id == instance_id:
                return card
        for card in player.unison_area:
            if card.instance_id == instance_id:
                return card
        return None

    @staticmethod
    def _clear_effect_state_for_source_instance(state: GameState, *, source_instance_id: int) -> None:
        removed_effect_ids = {
            reg.effect_id
            for reg in state.effect_registry
            if int(reg.source_instance_id) == int(source_instance_id)
        }
        if removed_effect_ids:
            state.effect_registry = [
                reg
                for reg in state.effect_registry
                if int(reg.source_instance_id) != int(source_instance_id)
            ]
            state.pending_effects = [
                row for row in state.pending_effects if int(row.effect_id) not in removed_effect_ids
            ]
            state.effect_resolutions = [
                row for row in state.effect_resolutions if int(row.effect_id) not in removed_effect_ids
            ]

    @staticmethod
    def _handler_params_signature(handler_params: dict[str, int | str | bool]) -> tuple[tuple[str, str], ...]:
        return tuple(sorted((str(key), str(value)) for key, value in dict(handler_params).items()))

    def _registration_matches_permanently_negated_skill(
        self,
        reg: EffectRegistration,
        row: PermanentlyNegatedSkill,
    ) -> bool:
        return (
            int(reg.source_instance_id) == int(row.source_instance_id)
            and str(reg.trigger) == str(row.trigger)
            and str(reg.handler_id) == str(row.handler_id)
            and self._handler_params_signature(reg.handler_params) == tuple(row.handler_params_signature)
        )

    def _is_registration_permanently_negated(self, state: GameState, reg: EffectRegistration) -> bool:
        return any(self._registration_matches_permanently_negated_skill(reg, row) for row in state.permanently_negated_skills)

    def _permanently_negate_registration_skill(self, state: GameState, reg: EffectRegistration) -> bool:
        row = PermanentlyNegatedSkill(
            source_instance_id=reg.source_instance_id,
            trigger=str(reg.trigger),
            handler_id=str(reg.handler_id),
            handler_params_signature=self._handler_params_signature(reg.handler_params),
        )
        if any(self._registration_matches_permanently_negated_skill(reg, existing) for existing in state.permanently_negated_skills):
            return False
        state.permanently_negated_skills.append(row)
        return True

    @staticmethod
    def _add_permanent_skill_activation_restriction(
        state: GameState,
        *,
        owner_player_id: int,
        restricted_card_id: int,
        scope: str,
        trigger: str = "",
        handler_id: str = "",
        handler_params_signature: tuple[tuple[str, str], ...] = (),
    ) -> bool:
        if any(
            int(row.owner_player_id) == int(owner_player_id)
            and int(row.restricted_card_id) == int(restricted_card_id)
            and str(row.scope) == str(scope)
            and str(row.trigger) == str(trigger)
            and str(row.handler_id) == str(handler_id)
            and tuple(row.handler_params_signature) == tuple(handler_params_signature)
            for row in state.permanent_skill_activation_restrictions
        ):
            return False
        state.permanent_skill_activation_restrictions.append(
            PermanentSkillActivationRestriction(
                owner_player_id=int(owner_player_id),
                restricted_card_id=int(restricted_card_id),
                scope=str(scope),
                trigger=str(trigger),
                handler_id=str(handler_id),
                handler_params_signature=tuple(handler_params_signature),
            )
        )
        return True

    def _is_registration_permanently_activation_restricted(self, state: GameState, reg: EffectRegistration) -> bool:
        scope = "activate" if str(reg.trigger) in {"self_activate_main", "self_activate_battle", "self_activate_extra_from_hand"} else "auto"
        return self._is_permanent_skill_activation_restricted(
            state,
            player_id=reg.owner_player_id,
            card_id=reg.source_card_id,
            scope=scope,
            trigger=str(reg.trigger),
            handler_id=str(reg.handler_id),
            handler_params_signature=self._handler_params_signature(reg.handler_params),
        )

    def _is_registration_temporarily_activation_restricted(self, state: GameState, reg: EffectRegistration) -> bool:
        scope = "activate" if str(reg.trigger) in {"self_activate_main", "self_activate_battle", "self_activate_extra_from_hand"} else "auto"
        return self._is_temporary_skill_activation_restricted(
            state,
            player_id=reg.owner_player_id,
            card_id=reg.source_card_id,
            scope=scope,
            trigger=str(reg.trigger),
            handler_id=str(reg.handler_id),
            handler_params_signature=self._handler_params_signature(reg.handler_params),
        ) or self._is_battle_skill_activation_restricted(
            state,
            player_id=reg.owner_player_id,
            card_id=reg.source_card_id,
            scope=scope,
            trigger=str(reg.trigger),
            handler_id=str(reg.handler_id),
            handler_params_signature=self._handler_params_signature(reg.handler_params),
        )

    def _add_temporary_skill_activation_restriction(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        restricted_card_id: int,
        scope: str,
        expires_on_turn_end_player_id: int,
        trigger: str = "",
        handler_id: str = "",
        handler_params_signature: tuple[tuple[str, str], ...] = (),
    ) -> bool:
        if self._is_temporary_skill_activation_restricted(
            state,
            player_id=owner_player_id,
            card_id=restricted_card_id,
            scope=scope,
            trigger=trigger,
            handler_id=handler_id,
            handler_params_signature=handler_params_signature,
        ):
            return False
        state.active_temporary_skill_activation_restrictions.append(
            TemporarySkillActivationRestriction(
                owner_player_id=owner_player_id,
                restricted_card_id=restricted_card_id,
                scope=scope,
                trigger=trigger,
                handler_id=handler_id,
                handler_params_signature=handler_params_signature,
                expires_on_turn_end_player_id=expires_on_turn_end_player_id,
            )
        )
        return True

    def _add_battle_skill_activation_restriction(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        restricted_card_id: int,
        scope: str,
        trigger: str = "",
        handler_id: str = "",
        handler_params_signature: tuple[tuple[str, str], ...] = (),
    ) -> bool:
        if self._is_battle_skill_activation_restricted(
            state,
            player_id=owner_player_id,
            card_id=restricted_card_id,
            scope=scope,
            trigger=trigger,
            handler_id=handler_id,
            handler_params_signature=handler_params_signature,
        ):
            return False
        state.active_battle_skill_activation_restrictions.append(
            BattleSkillActivationRestriction(
                owner_player_id=owner_player_id,
                restricted_card_id=restricted_card_id,
                scope=scope,
                trigger=trigger,
                handler_id=handler_id,
                handler_params_signature=handler_params_signature,
            )
        )
        return True

    def _registration_source_skill_text(self, state: GameState, reg: EffectRegistration) -> str:
        if str(getattr(reg, "source_skill_text", "") or "").strip():
            return str(getattr(reg, "source_skill_text", "") or "")
        found = self._find_card_anywhere_by_instance(
            state,
            owner_player_id=reg.owner_player_id,
            instance_id=reg.source_instance_id,
        )
        if found is not None:
            _zone, card = found
            if str(card.skill_text_raw or "").strip():
                return str(card.skill_text_raw or "")
        return str(self._resolve_card_runtime_data(reg.source_card_id).skill_text_raw or "")

    def _apply_post_resolution_registration_effects(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        text = self._registration_source_skill_text(state, reg)
        if self._text_play_restricts_copies_for_game(text):
            exists = any(
                int(row.owner_player_id) == int(reg.owner_player_id)
                and int(row.restricted_card_id) == int(reg.source_card_id)
                for row in state.permanent_card_play_restrictions
            )
            if not exists:
                state.permanent_card_play_restrictions.append(
                    PermanentCardRestriction(
                        owner_player_id=reg.owner_player_id,
                        restricted_card_id=reg.source_card_id,
                    )
                )
                state.log.append(
                    "Card plays on copies permanently restricted for the game: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_play_copies_restricted_for_game")
        if self._text_combo_restricts_copies_for_game(text):
            exists = any(
                int(row.owner_player_id) == int(reg.owner_player_id)
                and int(row.restricted_card_id) == int(reg.source_card_id)
                for row in state.permanent_combo_restrictions
            )
            if not exists:
                state.permanent_combo_restrictions.append(
                    PermanentCardRestriction(
                        owner_player_id=reg.owner_player_id,
                        restricted_card_id=reg.source_card_id,
                    )
                )
                state.log.append(
                    "Card combos on copies permanently restricted for the game: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_combo_copies_restricted_for_game")
        if self._text_play_restricts_copies_for_turn(text):
            exists = any(
                int(row.owner_player_id) == int(reg.owner_player_id)
                and int(row.restricted_card_id) == int(reg.source_card_id)
                for row in state.active_card_play_restrictions
            )
            if not exists:
                state.active_card_play_restrictions.append(
                    DelayedCardPlayRestriction(
                        owner_player_id=reg.owner_player_id,
                        restricted_card_id=reg.source_card_id,
                    )
                )
                state.log.append(
                    "Card plays on copies temporarily restricted for the turn: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_play_copies_restricted_for_turn")
        if self._text_combo_restricts_copies_for_turn(text):
            exists = any(
                int(row.owner_player_id) == int(reg.owner_player_id)
                and int(row.restricted_card_id) == int(reg.source_card_id)
                and int(row.expires_on_turn_end_player_id) == int(state.active_player)
                for row in state.active_combo_restrictions
            )
            if not exists:
                state.active_combo_restrictions.append(
                    TemporaryComboRestriction(
                        owner_player_id=reg.owner_player_id,
                        restricted_card_id=reg.source_card_id,
                        expires_on_turn_end_player_id=state.active_player,
                    )
                )
                state.log.append(
                    "Card combos on copies temporarily restricted for the turn: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_combo_copies_restricted_for_turn")
        if self._text_all_skills_restricts_copies_for_turn(text):
            if self._add_temporary_skill_activation_restriction(
                state,
                owner_player_id=reg.owner_player_id,
                restricted_card_id=reg.source_card_id,
                scope="any",
                expires_on_turn_end_player_id=state.active_player,
            ):
                state.log.append(
                    "All skills on copies temporarily restricted for the turn: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_all_skill_copies_restricted_for_turn")
        if self._text_all_skills_restricts_copies_for_game(text):
            if self._add_permanent_skill_activation_restriction(
                state,
                owner_player_id=reg.owner_player_id,
                restricted_card_id=reg.source_card_id,
                scope="any",
            ):
                state.log.append(
                    "All skills on copies permanently restricted for the game: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_all_skill_copies_restricted_for_game")
        if event.name == "skill_activated" and bool(reg.handler_params.get("negate_self_skill_for_game", False)):
            if self._permanently_negate_registration_skill(state, reg):
                state.log.append(
                    "Skill permanently negated for the game: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_skill_negated_for_game")
        if event.name == "skill_activated":
            skill_kind = str(event.payload.get("skill_kind") or "")
            if (
                str(reg.trigger) in {"self_activate_main", "self_activate_battle", "self_activate_extra_from_hand"}
                and self._text_activate_restricts_copies_for_game(text, skill_kind=skill_kind)
                and self._add_permanent_skill_activation_restriction(
                    state,
                    owner_player_id=reg.owner_player_id,
                    restricted_card_id=reg.source_card_id,
                    scope="activate",
                    trigger=str(reg.trigger),
                    handler_id=str(reg.handler_id),
                    handler_params_signature=self._handler_params_signature(reg.handler_params),
                )
            ):
                state.log.append(
                    "Activate copies permanently restricted for the game: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_activate_copies_restricted_for_game")
            if (
                str(reg.trigger) in {"self_activate_main", "self_activate_battle", "self_activate_extra_from_hand"}
                and self._text_activate_restricts_copies_for_turn(text, skill_kind=skill_kind)
                and self._add_temporary_skill_activation_restriction(
                    state,
                    owner_player_id=reg.owner_player_id,
                    restricted_card_id=reg.source_card_id,
                    scope="activate",
                    expires_on_turn_end_player_id=state.active_player,
                    trigger=str(reg.trigger),
                    handler_id=str(reg.handler_id),
                    handler_params_signature=self._handler_params_signature(reg.handler_params),
                )
            ):
                state.log.append(
                    "Activate copies temporarily restricted for the turn: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_activate_copies_restricted_for_turn")
            return
        if self._text_auto_restricts_copies_for_game(text):
            if self._add_permanent_skill_activation_restriction(
                state,
                owner_player_id=reg.owner_player_id,
                restricted_card_id=reg.source_card_id,
                scope="auto",
                trigger=str(reg.trigger),
                handler_id=str(reg.handler_id),
                handler_params_signature=self._handler_params_signature(reg.handler_params),
            ):
                state.log.append(
                    "Auto copies permanently restricted for the game: "
                    f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_auto_copies_restricted_for_game")
            return
        if not self._text_auto_restricts_copies_for_turn(text):
            return
        if self._add_temporary_skill_activation_restriction(
            state,
            owner_player_id=reg.owner_player_id,
            restricted_card_id=reg.source_card_id,
            scope="auto",
            expires_on_turn_end_player_id=state.active_player,
            trigger=str(reg.trigger),
            handler_id=str(reg.handler_id),
            handler_params_signature=self._handler_params_signature(reg.handler_params),
        ):
            state.log.append(
                "Auto copies temporarily restricted for the turn: "
                f"source_instance_id={reg.source_instance_id} trigger={reg.trigger} handler={reg.handler_id}"
            )
            self._checkpoint(state, "effect_auto_copies_restricted_for_turn")

    @staticmethod
    def _strip_card_skill_flags(card: CardInstance) -> None:
        card.keywords = ()
        card.counter_modes = ()
        card.temporary_keywords = ()
        card.battle_temporary_keywords = ()
        card.delayed_temporary_keywords = ()
        card.temporary_keyword_skills_negated = False
        card.has_counter = False
        card.has_counter_attack = False
        card.has_counter_battle_card_attack = False
        card.has_counter_play = False
        card.has_counter_counter = False
        card.has_activate_main = False
        card.has_activate_battle = False
        card.has_auto = False
        card.has_permanent = False
        card.has_draw = False
        card.max_draw = None
        card.auto_once_per_turn = False
        card.auto_draw_on_play = False
        card.auto_draw_on_attack = False
        card.has_barrier = False

    def _negate_card_skills_for_game(self, state: GameState, *, card: CardInstance) -> None:
        self._clear_effect_state_for_source_instance(state, source_instance_id=card.instance_id)
        self._strip_card_skill_flags(card)
        card.temporary_skills_negated = False
        card.permanent_skills_negated = True

    def _transfer_board_card_control(
        self,
        state: GameState,
        *,
        from_player_id: int,
        to_player_id: int,
        zone: str,
        instance_id: int,
        negate_skills_for_game: bool = False,
    ) -> CardInstance | None:
        if int(from_player_id) == int(to_player_id):
            player = state.players.get(from_player_id)
            if player is None:
                return None
            return self._find_by_instance(player, zone, instance_id)
        from_player = state.players.get(from_player_id)
        to_player = state.players.get(to_player_id)
        if from_player is None or to_player is None:
            return None
        if zone == "unison":
            source_zone = from_player.unison_area
            dest_zone = to_player.unison_area
        else:
            source_zone = from_player.battle_area
            dest_zone = to_player.battle_area
        idx = next((i for i, card in enumerate(source_zone) if int(card.instance_id) == int(instance_id)), -1)
        if idx < 0:
            return None
        moved = source_zone.pop(idx)
        self._clear_effect_state_for_source_instance(state, source_instance_id=moved.instance_id)
        if zone == "unison":
            self._replace_owner_unison_if_needed(state, to_player)
        dest_zone.append(moved)
        if negate_skills_for_game:
            self._negate_card_skills_for_game(state, card=moved)
        else:
            self._register_card_effects(state, player_id=to_player_id, source_zone=zone, card=moved)
        return moved

    def _send_board_card_to_owner_out_of_play(
        self,
        state: GameState,
        *,
        controller_player_id: int,
        zone: str,
        instance_id: int,
        destination: str,
        source_zone_for_event: str | None = None,
        emit_removed_event: bool = False,
    ) -> CardInstance | None:
        controller = state.players.get(controller_player_id)
        if controller is None:
            return None
        zone_cards = controller.unison_area if zone == "unison" else controller.battle_area
        idx = next((i for i, card in enumerate(zone_cards) if int(card.instance_id) == int(instance_id)), -1)
        if idx < 0:
            return None
        removed = zone_cards.pop(idx)
        owner_player_id = int(getattr(removed, "owner_id", controller_player_id) or controller_player_id)
        owner = state.players.get(owner_player_id)
        if owner is None:
            return None
        if destination == "removed":
            owner.removed_from_game.append(removed)
            if emit_removed_event:
                self._emit_card_removed_from_game(
                    state,
                    owner_player_id=owner_player_id,
                    card=removed,
                    source_zone=source_zone_for_event or zone,
                )
        elif destination == "warp":
            self._append_to_owner_warp(
                state,
                owner_player_id=owner_player_id,
                card=removed,
                source_zone=source_zone_for_event or zone,
            )
        else:
            owner.drop.append(removed)
            self._emit_board_card_placed_into_drop(
                state,
                owner_player_id=owner_player_id,
                card=removed,
                source_zone=source_zone_for_event or zone,
            )
        return removed

    def _schedule_delayed_mode_switch(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        target_instance_id: int,
        trigger_kind: str,
        trigger_player_id: int,
        switch_to_hidden: bool,
    ) -> None:
        state.delayed_mode_switches.append(
            DelayedModeSwitch(
                owner_player_id=owner_player_id,
                target_instance_id=target_instance_id,
                trigger_kind=trigger_kind,
                trigger_player_id=trigger_player_id,
                switch_to_hidden=switch_to_hidden,
            )
        )

    def _schedule_delayed_active_switch(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        target_instance_id: int,
        trigger_player_id: int,
    ) -> None:
        state.delayed_active_switches.append(
            DelayedActiveSwitch(
                owner_player_id=owner_player_id,
                target_instance_id=target_instance_id,
                trigger_player_id=trigger_player_id,
            )
        )

    def _schedule_delayed_main_phase_energy_switch(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        trigger_player_id: int,
        max_targets: int,
        allowed_colors: str = "",
        requires_multicolor: bool = False,
    ) -> None:
        state.delayed_main_phase_energy_switches.append(
            DelayedMainPhaseEnergySwitch(
                owner_player_id=owner_player_id,
                trigger_player_id=trigger_player_id,
                max_targets=max_targets,
                allowed_colors=allowed_colors,
                requires_multicolor=requires_multicolor,
            )
        )

    def _schedule_delayed_warp(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        target_instance_id: int,
        trigger_player_id: int,
    ) -> None:
        state.delayed_warps.append(
            DelayedWarp(
                owner_player_id=owner_player_id,
                target_instance_id=target_instance_id,
                trigger_player_id=trigger_player_id,
            )
        )

    def _apply_due_delayed_mode_switches(self, state: GameState, *, trigger_kind: str, trigger_player_id: int) -> None:
        if not state.delayed_mode_switches:
            return
        remaining: list[DelayedModeSwitch] = []
        changed = False
        for delayed in state.delayed_mode_switches:
            if delayed.trigger_kind != trigger_kind or delayed.trigger_player_id != trigger_player_id:
                remaining.append(delayed)
                continue
            owner = state.players.get(delayed.owner_player_id)
            if owner is None:
                continue
            target = self._find_board_card_by_instance(owner, delayed.target_instance_id)
            if target is None:
                continue
            target.hidden_mode = bool(delayed.switch_to_hidden)
            changed = True
            event_name = "card_switched_hidden_mode" if delayed.switch_to_hidden else "card_switched_revealed_mode"
            self._emit_effect_event(
                state,
                name=event_name,
                actor_player_id=delayed.owner_player_id,
                payload={
                    "source_instance_id": target.instance_id,
                    "source_card_id": target.card_id,
                    "source_zone": "unison" if target in owner.unison_area else "battle",
                    "owner_player_id": delayed.owner_player_id,
                },
            )
        state.delayed_mode_switches = remaining
        if changed:
            self._checkpoint(state, "delayed_mode_switch_resolved")

    def _apply_due_delayed_active_switches(self, state: GameState, *, trigger_player_id: int) -> None:
        if not state.delayed_active_switches:
            return
        remaining: list[DelayedActiveSwitch] = []
        changed = False
        for delayed in state.delayed_active_switches:
            if delayed.trigger_player_id != trigger_player_id:
                remaining.append(delayed)
                continue
            found = self._find_card_anywhere_by_instance(
                state,
                owner_player_id=delayed.owner_player_id,
                instance_id=delayed.target_instance_id,
            )
            if found is None:
                continue
            _zone, target = found
            if target.resting and self._can_switch_card_to_active(target):
                target.resting = False
                changed = True
        state.delayed_active_switches = remaining
        if changed:
            self._checkpoint(state, "delayed_active_switch_resolved")

    def _apply_due_delayed_main_phase_energy_switches(self, state: GameState, *, trigger_player_id: int) -> None:
        if not state.delayed_main_phase_energy_switches:
            return
        remaining: list[DelayedMainPhaseEnergySwitch] = []
        changed = False
        for delayed in state.delayed_main_phase_energy_switches:
            if delayed.trigger_player_id != trigger_player_id:
                remaining.append(delayed)
                continue
            owner = state.players.get(delayed.owner_player_id)
            if owner is None:
                continue
            candidates = [c for c in owner.energy if c.resting]
            allowed_colors = {
                c.strip()
                for c in str(delayed.allowed_colors).replace("/", ",").replace("|", ",").split(",")
                if c.strip()
            }
            if allowed_colors:
                filtered: list[CardInstance] = []
                for c in candidates:
                    colors = {p.strip().lower() for p in str(c.color or "").replace("/", ",").split(",") if p.strip()}
                    if colors and colors.isdisjoint(allowed_colors):
                        continue
                    filtered.append(c)
                candidates = filtered
            if delayed.requires_multicolor:
                candidates = [c for c in candidates if "/" in str(c.color or "")]
            activated = 0
            for c in candidates:
                if activated >= max(int(delayed.max_targets), 0):
                    break
                if not self._can_switch_card_to_active(c):
                    continue
                c.resting = False
                activated += 1
            if activated > 0:
                changed = True
        state.delayed_main_phase_energy_switches = remaining
        if changed:
            self._checkpoint(state, "delayed_main_phase_energy_switch_resolved")

    def _apply_due_delayed_warps(self, state: GameState, *, trigger_player_id: int) -> None:
        if not state.delayed_warps:
            return
        remaining: list[DelayedWarp] = []
        changed = False
        for delayed in state.delayed_warps:
            if delayed.trigger_player_id != trigger_player_id:
                remaining.append(delayed)
                continue
            found = self._find_card_anywhere_by_instance(
                state,
                owner_player_id=delayed.owner_player_id,
                instance_id=delayed.target_instance_id,
            )
            if found is None:
                continue
            zone_name, target = found
            owner = state.players.get(delayed.owner_player_id)
            if owner is None:
                continue
            if zone_name == "leader":
                remaining.append(delayed)
                continue
            zone_cards = (
                owner.hand
                if zone_name == "hand"
                else owner.life
                if zone_name == "life"
                else owner.energy
                if zone_name == "energy"
                else owner.z_energy
                if zone_name == "z_energy"
                else owner.battle_area
                if zone_name == "battle"
                else owner.unison_area
                if zone_name == "unison"
                else owner.combo_area
                if zone_name == "combo"
                else owner.drop
                if zone_name == "drop"
                else owner.warp
                if zone_name == "warp"
                else owner.removed_from_game
                if zone_name == "removed_from_game"
                else None
            )
            if zone_cards is None:
                continue
            for idx, card in enumerate(zone_cards):
                if int(card.instance_id) != int(delayed.target_instance_id):
                    continue
                moved = zone_cards.pop(idx)
                self._append_to_owner_warp(
                    state,
                    owner_player_id=delayed.owner_player_id,
                    card=moved,
                    source_zone=zone_name,
                )
                changed = True
                break
        state.delayed_warps = remaining
        if changed:
            self._checkpoint(state, "delayed_warp_resolved")

    def _apply_due_delayed_keyword_clears(self, state: GameState, *, trigger_player_id: int) -> None:
        if not state.delayed_keyword_clears:
            return
        remaining: list[DelayedKeywordClear] = []
        changed = False
        for delayed in state.delayed_keyword_clears:
            if delayed.trigger_player_id != trigger_player_id:
                remaining.append(delayed)
                continue
            owner = state.players.get(delayed.owner_player_id)
            if owner is None:
                continue
            target = self._find_board_card_by_instance(owner, delayed.target_instance_id)
            if target is None and owner.leader_area.instance_id == delayed.target_instance_id:
                target = owner.leader_area
            if target is None:
                continue
            filtered = tuple(
                item
                for item in (target.delayed_temporary_keywords or ())
                if str(item).strip().lower() != delayed.keyword.strip().lower()
            )
            if filtered != target.delayed_temporary_keywords:
                target.delayed_temporary_keywords = filtered
                changed = True
        state.delayed_keyword_clears = remaining
        if changed:
            self._checkpoint(state, "delayed_keyword_clear_resolved")

    def _ko_card(self, state: GameState, player_id: int, zone: str, instance_id: int) -> None:
        player = state.players[player_id]
        zone_cards = player.battle_area if zone == "battle" else player.unison_area
        for i, c in enumerate(zone_cards):
            if c.instance_id == instance_id:
                removed = self._send_board_card_to_owner_out_of_play(
                    state,
                    controller_player_id=player_id,
                    zone=zone,
                    instance_id=instance_id,
                    destination="removed" if c.card_type.startswith("Z-") else "drop",
                )
                if removed is None:
                    return
                self._emit_effect_event(
                    state,
                    name="card_koed",
                    actor_player_id=None,
                    payload={
                        "source_instance_id": removed.instance_id,
                        "source_card_id": removed.card_id,
                        "source_zone": zone,
                        "owner_player_id": removed.owner_id,
                    },
                )
                self._checkpoint(state, "ko_processing")
                return

    def _emit_card_placed_into_drop(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        card: CardInstance,
        source_zone: str,
        drop_cause: str | None = None,
    ) -> None:
        self._emit_effect_event(
            state,
            name="card_placed_into_drop",
            actor_player_id=None,
            payload={
                "source_instance_id": card.instance_id,
                "source_card_id": card.card_id,
                "source_zone": source_zone,
                "owner_player_id": owner_player_id,
                "source_hidden_mode": bool(card.hidden_mode),
                "source_keywords": ",".join(str(item).strip() for item in (card.keywords or ()) if str(item).strip()),
                "drop_cause": drop_cause,
            },
        )
        self._register_card_effects(state, player_id=owner_player_id, source_zone="drop", card=card)

    def _emit_card_removed_from_game(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        card: CardInstance,
        source_zone: str,
    ) -> None:
        self._emit_effect_event(
            state,
            name="card_removed_from_game",
            actor_player_id=owner_player_id,
            payload={
                "source_instance_id": card.instance_id,
                "source_card_id": card.card_id,
                "source_zone": source_zone,
                "owner_player_id": owner_player_id,
                },
            )

    def _emit_card_placed_under_card(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        host: CardInstance,
        host_zone: str,
        card: CardInstance,
        source_zone: str,
        placed_by: str = "",
    ) -> None:
        self._register_card_effects(state, player_id=owner_player_id, source_zone=source_zone, card=card)
        self._emit_effect_event(
            state,
            name="card_placed_under_card",
            actor_player_id=owner_player_id,
            payload={
                "source_instance_id": card.instance_id,
                "source_card_id": card.card_id,
                "source_zone": "under",
                "placed_from": source_zone,
                "owner_player_id": owner_player_id,
                "host_instance_id": host.instance_id,
                "host_card_id": host.card_id,
                "host_zone": host_zone,
                "host_owner_player_id": owner_player_id,
                "placed_by": placed_by,
            },
        )
        event = state.effect_events[-1]
        for reg in list(state.effect_registry):
            if int(reg.source_instance_id) != int(card.instance_id):
                continue
            if str(reg.trigger or "").strip().lower() not in {"self_placed_under_owner_card", "self_placed_under_by_union"}:
                continue
            if not self._effect_registration_matches_event(reg, event):
                continue
            handler = self._effect_handlers.get(str(reg.handler_id or ""))
            if handler is None:
                continue
            handler(state, event, reg)

    def _emit_board_card_placed_into_drop(self, state: GameState, *, owner_player_id: int, card: CardInstance, source_zone: str) -> None:
        self._emit_card_placed_into_drop(state, owner_player_id=owner_player_id, card=card, source_zone=source_zone)

    def _append_to_owner_warp(self, state: GameState, *, owner_player_id: int, card: CardInstance, source_zone: str | None = None) -> None:
        owner = state.players[owner_player_id]
        owner.warp.append(card)
        if source_zone:
            self._emit_effect_event(
                state,
                name="card_sent_to_warp",
                actor_player_id=None,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": source_zone,
                    "owner_player_id": owner_player_id,
                    "source_hidden_mode": bool(card.hidden_mode),
                },
            )
        self._register_card_effects(state, player_id=owner_player_id, source_zone="warp", card=card)

    @staticmethod
    def _place_card_under_host(host: CardInstance, card: CardInstance) -> None:
        host.stacked_card_ids = tuple(host.stacked_card_ids) + (int(card.card_id),)

    def _preferred_keyword_from_card_ids(self, card_ids: tuple[int, ...]) -> str:
        ignored = {
            "auto",
            "permanent",
            "once per turn",
            "activate: main",
            "activate main",
            "activate: battle",
            "activate battle",
            "activate: main/battle",
            "activate main/battle",
            "counter",
        }
        preferred_order = (
            "deflect",
            "barrier",
            "blocker",
            "dual attack",
            "double strike",
            "triple strike",
            "critical",
            "wormhole",
        )
        found: list[str] = []
        for card_id in card_ids:
            runtime = self._resolve_card_runtime_data(int(card_id))
            for raw in getattr(runtime, "keywords", ()) or ():
                keyword = str(raw).strip()
                lowered = keyword.lower()
                if not keyword or lowered in ignored or lowered.startswith("limit ") or lowered.startswith("z-stack"):
                    continue
                if keyword not in found:
                    found.append(keyword)
        for preferred in preferred_order:
            for keyword in found:
                if keyword.lower() == preferred:
                    return keyword
        return found[0] if found else ""

    def _release_under_cards_to_drop(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        host: CardInstance,
        source_zone: str = "under",
    ) -> int:
        owner = state.players[owner_player_id]
        released = 0
        for card_id in list(host.stacked_card_ids):
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=int(card_id), owner_id=owner_player_id)
            state.next_instance_id += 1
            owner.drop.append(card)
            self._emit_card_placed_into_drop(state, owner_player_id=owner_player_id, card=card, source_zone=source_zone)
            released += 1
        host.stacked_card_ids = ()
        return released

    def _replace_owner_unison_if_needed(self, state: GameState, player: PlayerState) -> CardInstance | None:
        if not player.unison_area:
            return None
        replaced = player.unison_area.pop()
        if replaced.card_type.startswith("Z-"):
            player.removed_from_game.append(replaced)
        else:
            player.drop.append(replaced)
        self._checkpoint(state, "unison_replaced")
        return replaced

    def _apply_unison_battle_damage(self, state: GameState, player_id: int, instance_id: int, attacker: CardInstance) -> None:
        player = state.players[player_id]
        for i, unison in enumerate(player.unison_area):
            if unison.instance_id != instance_id:
                continue
            if "Victory Strike" in attacker.keywords:
                remove = unison.markers
            elif any(k in attacker.keywords for k in ("Double Strike", "Triple Strike", "Quadruple Strike")):
                remove = self._strike_damage(attacker)
            else:
                remove = 1
            self._remove_unison_markers(state, unison=unison, amount=remove, reason="battle_damage")
            if unison.markers <= 0:
                removed = player.unison_area.pop(i)
                if removed.card_type.startswith("Z-"):
                    player.removed_from_game.append(removed)
                else:
                    player.drop.append(removed)
            self._checkpoint(state, "unison_marker_damage")
            return

    def _cleanup_combo_areas(self, state: GameState) -> None:
        for p in state.players.values():
            while p.combo_area:
                p.drop.append(p.combo_area.pop())
        self._checkpoint(state, "battle_combo_cleanup")

    def _deal_damage_to_player(self, state: GameState, player_id: int, amount: int) -> None:
        if amount <= 0:
            return
        player = state.players[player_id]
        for damage_index in range(amount):
            if not player.life:
                break
            chosen_index = self._choose_life_card_index(player, damage_index)
            player.hand.append(player.life.pop(chosen_index))
        self._checkpoint(state, "damage_processing")

    def _choose_life_card_index(self, player: PlayerState, damage_index: int) -> int:
        if not player.life:
            return 0
        max_index = len(player.life) - 1
        if self._life_card_chooser is None:
            return 0
        try:
            selected = int(self._life_card_chooser(player, damage_index, max_index))
        except Exception:
            return 0
        if selected < 0:
            return 0
        if selected > max_index:
            return max_index
        return selected

    def _after_action(self, state: GameState) -> None:
        self._run_confirmative_rule_processing(state)
        self._evaluate_continuous_effects(state)
        # Checkpoint-equivalent resolution is deferred while a counter window is open.
        if state.counter_window is None:
            self._resolve_pending_effects(state)
        self._check_loss_conditions(state)

    def _run_confirmative_rule_processing(self, state: GameState) -> None:
        self._prune_stale_deferred_secret_autos(state)
        self._prune_stale_secret_auto_opportunities(state)
        for player in state.players.values():
            i = 0
            while i < len(player.battle_area):
                if player.battle_area[i].power <= 0:
                    self._send_board_card_to_owner_out_of_play(
                        state,
                        controller_player_id=player.player_id,
                        zone="battle",
                        instance_id=player.battle_area[i].instance_id,
                        destination="drop",
                    )
                    self._checkpoint(state, "rule_battle_power_zero")
                    continue
                i += 1

            i = 0
            while i < len(player.unison_area):
                unison = player.unison_area[i]
                if "UNISON" not in (unison.card_type or "").upper():
                    i += 1
                    continue
                if unison.power <= 0:
                    self._remove_unison_markers(state, unison=unison, amount=1, reason="rule_power_zero")
                if unison.markers <= 0:
                    self._send_board_card_to_owner_out_of_play(
                        state,
                        controller_player_id=player.player_id,
                        zone="unison",
                        instance_id=unison.instance_id,
                        destination="removed" if unison.card_type.startswith("Z-") else "drop",
                    )
                    self._checkpoint(state, "rule_unison_zero_markers")
                    continue
                if unison.power <= 0:
                    # Confirmative checks repeat until no zero-power unison remains.
                    continue
                i += 1

    def _prune_stale_deferred_secret_autos(self, state: GameState) -> None:
        retained: list[DeferredSecretAuto] = []
        removed_any = False
        for row in state.deferred_secret_autos:
            if self._deferred_secret_auto_source_exists(state, row):
                retained.append(row)
            else:
                removed_any = True
        if removed_any:
            state.deferred_secret_autos = retained
            self._checkpoint(state, "secret_auto_registration_pruned")

    def _prune_stale_secret_auto_opportunities(self, state: GameState) -> None:
        retained: list[SecretAutoOpportunity] = []
        removed_any = False
        for row in state.secret_auto_opportunities:
            if row.status != "pending":
                retained.append(row)
                continue
            if self._find_card_anywhere_by_instance(
                state,
                owner_player_id=row.owner_player_id,
                instance_id=row.source_instance_id,
            ) is not None:
                retained.append(row)
                continue
            removed_any = True
        if removed_any:
            state.secret_auto_opportunities = retained
            self._checkpoint(state, "secret_auto_opportunity_pruned")

    def _deferred_secret_auto_source_exists(self, state: GameState, row: DeferredSecretAuto) -> bool:
        player = state.players.get(row.owner_player_id)
        if player is None:
            return False
        zone = str(row.source_zone or "").strip().lower()
        if zone == "hand":
            return any(card.instance_id == row.source_instance_id for card in player.hand)
        if zone == "life":
            return any(card.instance_id == row.source_instance_id for card in player.life)
        if zone == "deck":
            return False
        return False

    def _modify_card_power(self, state: GameState, *, card: CardInstance, delta: int, reason: str) -> None:
        if delta == 0:
            return
        self._set_card_power(state, card=card, new_power=card.power + delta, reason=reason)

    def _set_card_power(self, state: GameState, *, card: CardInstance, new_power: int, reason: str) -> None:
        if card.power == new_power:
            return
        self._checkpoint(state, f"power_change_begin_{reason}")
        card.power = new_power
        self._checkpoint(state, f"power_changed_{reason}")

    def _can_pay_skill_cost(self, player: PlayerState, card: CardInstance, context: str, *, source_zone: str | None = None) -> bool:
        if self._skill_cost_can_pay is None:
            spec = self._resolve_skill_cost_spec(card.card_id, context, source_zone=source_zone)
            if spec is None:
                return True
            try:
                return SkillCostDsl.can_pay(player, card, spec)
            except Exception:
                return False
        try:
            return bool(self._skill_cost_can_pay(player, card, context))
        except Exception:
            return False

    def _pay_skill_cost(self, state: GameState, player: PlayerState, card: CardInstance, context: str, *, source_zone: str | None = None) -> dict[str, int | str | None]:
        if self._skill_cost_pay is None:
            spec = self._resolve_skill_cost_spec(card.card_id, context, source_zone=source_zone)
            if spec is None:
                return {}
            try:
                before_markers = card.markers
                metadata = SkillCostDsl.pay(player, card, spec)
                removed_markers = max(before_markers - card.markers, 0)
                if removed_markers > 0 and card.card_type in {"UNISON", "Z-UNISON"}:
                    self._checkpoint(state, "marker_remove_begin_skill_cost")
                    self._checkpoint(state, "marker_removed_skill_cost")
                self._emit_drop_event_from_skill_cost_metadata(state, player=player, metadata=metadata)
                return dict(metadata)
            except Exception as exc:
                raise RulesViolation(f"Skill cost payment failed: {exc}") from exc
        try:
            metadata = self._skill_cost_pay(player, card, context)
            if isinstance(metadata, dict):
                normalized = {str(k): v for k, v in metadata.items() if isinstance(k, str) and isinstance(v, (int, str, bool, type(None)))}
                self._emit_drop_event_from_skill_cost_metadata(state, player=player, metadata=normalized)
                return normalized
            return {}
        except Exception as exc:
            raise RulesViolation(f"Skill cost payment failed: {exc}") from exc

    def _emit_drop_event_from_skill_cost_metadata(
        self,
        state: GameState,
        *,
        player: PlayerState,
        metadata: dict[str, int | str | None],
    ) -> None:
        target_instance_id = int(metadata.get("cost_target_instance_id") or -1)
        target_zone = str(metadata.get("cost_target_zone") or "")
        removed_source_instance_id = int(metadata.get("removed_source_instance_id") or -1)
        removed_source_zone = str(metadata.get("removed_source_zone") or "")
        if removed_source_instance_id > 0:
            removed = next((card for card in player.removed_from_game if card.instance_id == removed_source_instance_id), None)
            if removed is not None:
                self._emit_card_removed_from_game(
                    state,
                    owner_player_id=player.player_id,
                    card=removed,
                    source_zone=removed_source_zone or "battle",
                )
        if target_instance_id <= 0:
            return
        target = next((card for card in player.drop if card.instance_id == target_instance_id), None)
        if target is None:
            return
        if target_zone == "battle":
            self._emit_card_placed_into_drop(
                state,
                owner_player_id=player.player_id,
                card=target,
                source_zone="battle",
                drop_cause="skill",
            )
            return
        if target_zone in {"hand", "unison", "warp"}:
            self._emit_card_placed_into_drop(state, owner_player_id=player.player_id, card=target, source_zone=target_zone)
            return
        if target_zone == "combo":
            self._emit_card_placed_into_drop(state, owner_player_id=player.player_id, card=target, source_zone=target_zone)

    def _remove_unison_markers(self, state: GameState, *, unison: CardInstance, amount: int, reason: str) -> None:
        if amount <= 0:
            return
        self._checkpoint(state, f"marker_remove_begin_{reason}")
        unison.markers -= amount
        self._checkpoint(state, f"marker_removed_{reason}")

    def _pay_spirit_boost_markers(self, state: GameState, *, player: PlayerState, amount: int, reason: str) -> None:
        remaining = max(int(amount or 0), 0)
        if remaining <= 0:
            return
        for unison in player.unison_area:
            if remaining <= 0:
                break
            available = max(int(getattr(unison, "markers", 0) or 0), 0)
            if available <= 0:
                continue
            remove_amount = min(available, remaining)
            self._remove_unison_markers(state, unison=unison, amount=remove_amount, reason=reason)
            remaining -= remove_amount
        if remaining > 0:
            raise RulesViolation("Not enough unison markers for Spirit Boost cost.")

    def _resolve_skill_cost_spec(self, card_id: int, context: str, *, source_zone: str | None = None) -> SkillCostSpec | None:
        card_rules = self._skill_cost_rules.get(card_id)
        if not card_rules:
            return None
        raw = None
        if source_zone:
            raw = card_rules.get(f"{context}_{str(source_zone).strip().lower()}")
        if raw is None:
            raw = card_rules.get(context)
        if raw is None:
            return None
        return SkillCostSpec.from_data(raw)

    @staticmethod
    def _is_valid_skill_source_area(card: CardInstance, zone: str | None) -> bool:
        if RulesEngine._card_skills_are_negated(card):
            return False
        if zone == "leader":
            return True
        if card.hidden_mode:
            return False
        ctype = (card.card_type or "").upper()
        if zone == "hand":
            return ctype in {"BATTLE", "UNISON", "Z-BATTLE", "Z-UNISON"}
        if zone == "warp":
            return ctype in {"BATTLE", "UNISON", "Z-BATTLE", "Z-UNISON"}
        if zone == "combo":
            return "BATTLE" in ctype
        if zone == "drop":
            return ctype in {"BATTLE", "UNISON", "Z-BATTLE", "Z-UNISON"}
        if zone == "battle":
            return "BATTLE" in ctype or ctype in {"EXTRA", "Z-EXTRA"}
        if zone == "unison":
            return "UNISON" in ctype
        return False

    @staticmethod
    def _strike_damage(card: CardInstance) -> int:
        if "Victory Strike" in card.keywords:
            return 999
        if "Quadruple Strike" in card.keywords:
            return 4
        if "Triple Strike" in card.keywords:
            return 3
        if "Double Strike" in card.keywords:
            return 2
        return 1

    def _strike_damage_against_target(
        self,
        state: GameState,
        *,
        attacker: CardInstance,
        target_player_id: int,
        target_zone: str,
    ) -> int:
        if target_zone == "leader" and int(target_player_id) in state.negate_opponent_strike_for_player_ids:
            return 1
        return self._strike_damage(attacker)

    @staticmethod
    def _can_pay_energy_cost(
        player: PlayerState,
        cost: int,
        *,
        required_color: str | None = None,
        specified_costs: dict[str, int] | None = None,
    ) -> bool:
        specified = {k: int(v) for k, v in (specified_costs or {}).items() if int(v) > 0}
        total_cost = max(int(cost), sum(specified.values()))
        if total_cost <= 0:
            return True
        active = [c for c in player.energy if not c.resting]
        if len(active) + player.energy_markers < total_cost:
            return False
        if specified:
            for color_code, needed in specified.items():
                matching_energy = sum(1 for c in active if RulesEngine._color_to_code(c.color) == color_code)
                if matching_energy + player.energy_markers < needed:
                    return False
            return True
        if not required_color:
            return True
        allowed = {x.strip().lower() for x in required_color.split("/")}
        if player.energy_markers > 0:
            return True
        return any((c.color or "").lower() in allowed for c in active)

    @staticmethod
    def _can_pay_z_energy_cost(player: PlayerState, z_cost: int) -> bool:
        return z_cost <= 0 or len(player.z_energy) >= z_cost

    @staticmethod
    def _can_pay_costs(
        player: PlayerState,
        *,
        energy_cost: int,
        required_color: str | None,
        specified_costs: dict[str, int] | None,
        z_cost: int,
    ) -> bool:
        return RulesEngine._can_pay_energy_cost(
            player,
            energy_cost,
            required_color=required_color,
            specified_costs=specified_costs,
        ) and RulesEngine._can_pay_z_energy_cost(player, z_cost)

    @staticmethod
    def _pay_energy_cost(
        player: PlayerState,
        cost: int,
        *,
        required_color: str | None = None,
        specified_costs: dict[str, int] | None = None,
    ) -> int:
        specified = {k: int(v) for k, v in (specified_costs or {}).items() if int(v) > 0}
        total_cost = max(int(cost), sum(specified.values()))
        if total_cost <= 0:
            return 0
        if not RulesEngine._can_pay_energy_cost(
            player,
            cost,
            required_color=required_color,
            specified_costs=specified_costs,
        ):
            raise RulesViolation("Not enough active energy/markers to pay cost.")
        rem = total_cost
        paid_by_energy = 0

        if specified:
            # Pay specified pips first from matching active energy.
            for color_code, needed in specified.items():
                for c in player.energy:
                    if needed <= 0:
                        break
                    if c.resting:
                        continue
                    if RulesEngine._color_to_code(c.color) == color_code:
                        c.resting = True
                        needed -= 1
                        rem -= 1
                        paid_by_energy += 1
                if needed > 0:
                    player.energy_markers -= needed
                    rem -= needed

        for c in player.energy:
            if rem == 0:
                break
            if not c.resting:
                c.resting = True
                rem -= 1
                paid_by_energy += 1
        if rem > 0:
            player.energy_markers -= rem
        return paid_by_energy

    @staticmethod
    def _pay_z_energy_cost(player: PlayerState, z_cost: int) -> int:
        if z_cost <= 0:
            return 0
        if len(player.z_energy) < z_cost:
            raise RulesViolation("Not enough Z-energy.")
        for _ in range(z_cost):
            player.drop.append(player.z_energy.pop())
        return z_cost

    @staticmethod
    def _pay_costs(
        player: PlayerState,
        *,
        energy_cost: int,
        required_color: str | None,
        specified_costs: dict[str, int] | None,
        z_cost: int,
    ) -> tuple[int, int]:
        if not RulesEngine._can_pay_costs(
            player,
            energy_cost=energy_cost,
            required_color=required_color,
            specified_costs=specified_costs,
            z_cost=z_cost,
        ):
            raise RulesViolation("Not enough resources.")
        paid_energy = RulesEngine._pay_energy_cost(
            player,
            energy_cost,
            required_color=required_color,
            specified_costs=specified_costs,
        )
        paid_z = RulesEngine._pay_z_energy_cost(player, z_cost)
        return paid_energy, paid_z

    def _register_card_effects(self, state: GameState, *, player_id: int, source_zone: str, card: CardInstance) -> None:
        candidates: list[tuple[str, str, bool | None, dict[str, int | str | bool], str]] = []
        deferred_secret_auto = False
        if not self._is_secret_zone(source_zone):
            self._promote_deferred_secret_autos_to_public_zone(
                state,
                source_instance_id=card.instance_id,
                source_zone=source_zone,
            )
        if card.has_auto:
            if source_zone in {"battle", "unison"}:
                candidates.append(("self_played", "noop_auto", None, {}, ""))
                if card.auto_draw_on_play:
                    candidates.append(("self_played", "auto_draw_on_play", None, {}, ""))
            if source_zone in {"leader", "battle", "unison"}:
                candidates.append(("self_attacks", "noop_auto", None, {}, ""))
                if card.auto_draw_on_attack:
                    candidates.append(("self_attacks", "auto_draw_on_attack", None, {}, ""))

        for rule in self._effect_rules.get(card.card_id, ()):
            params = dict(rule.handler_params)
            if rule.limit_per_turn is not None:
                params["limit_per_turn"] = int(rule.limit_per_turn)
                params["limit_scope"] = str(rule.limit_scope or "card_number")
            if not self._can_register_effect_trigger_from_zone(source_zone, rule.trigger):
                if self._is_secret_zone(source_zone):
                    deferred_secret_auto = True
                    self._record_deferred_secret_auto(
                        state,
                        owner_player_id=player_id,
                        card=card,
                        source_zone=source_zone,
                        trigger=rule.trigger,
                        handler_id=rule.handler_id,
                        handler_params=params,
                        source_skill_text=str(rule.source_text or ""),
                        once_per_turn=bool(rule.once_per_turn),
                        limit_per_turn=rule.limit_per_turn,
                        limit_scope=str(rule.limit_scope or "card_number"),
                    )
                    state.log.append(
                        "Deferred secret-area auto registration: "
                        f"source_instance_id={card.instance_id} zone={source_zone} trigger={rule.trigger}"
                    )
                continue
            candidates.append((rule.trigger, rule.handler_id, rule.once_per_turn, params, str(rule.source_text or "")))

        for trigger, handler_id, once_per_turn_override, handler_params, source_skill_text in candidates:
            linked_secret = self._find_linked_deferred_secret_auto(
                state,
                source_instance_id=card.instance_id,
                trigger=trigger,
                handler_id=handler_id,
                handler_params=handler_params,
                source_skill_text=source_skill_text,
            )
            if linked_secret is not None and self._preserve_secret_auto_provenance_on_public_registration(
                linked_secret,
                source_zone=source_zone,
            ):
                continue
            exists = any(
                reg.source_instance_id == card.instance_id
                and reg.source_zone == source_zone
                and reg.trigger == trigger
                and reg.handler_id == handler_id
                and str(reg.source_skill_text or "") == str(source_skill_text or "")
                for reg in state.effect_registry
            )
            if exists:
                continue
            state.effect_registry.append(
                EffectRegistration(
                    effect_id=state.next_effect_id,
                    owner_player_id=player_id,
                    source_instance_id=card.instance_id,
                    source_card_id=card.card_id,
                    source_zone=source_zone,
                    trigger=trigger,
                    handler_id=handler_id,
                    handler_params=dict(handler_params),
                    source_skill_text=source_skill_text,
                    source_card_number=str(card.card_number or ""),
                    once_per_turn=card.auto_once_per_turn if once_per_turn_override is None else bool(once_per_turn_override),
                    limit_per_turn=self._resolve_effect_limit_per_turn(handler_params),
                    limit_scope=str(handler_params.get("limit_scope", "card_number") or "card_number"),
                )
            )
            state.next_effect_id += 1
        if deferred_secret_auto:
            self._checkpoint(state, "secret_auto_registration_deferred")
        if str(source_zone or "").strip().lower() == "leader":
            self._register_leader_under_card_effects(state, player_id=player_id)

    @staticmethod
    def _can_register_effect_trigger_from_zone(source_zone: str, trigger: str) -> bool:
        normalized_zone = str(source_zone or "").strip().lower()
        if normalized_zone in {"hand", "life", "deck"}:
            return trigger in {"self_activate_main", "self_activate_battle", "self_placed_under_owner_card", "self_placed_under_by_union"}
        if normalized_zone == "drop":
            return trigger in {"owner_opponent_battle_attacks", "self_activate_extra_from_hand", "self_activate_main"}
        if normalized_zone == "warp":
            return trigger in {"owner_opponent_battle_attacks", "self_activate_main", "self_activate_battle"}
        return True

    @staticmethod
    def _is_secret_zone(source_zone: str) -> bool:
        return str(source_zone or "").strip().lower() in {"hand", "life", "deck"}

    @staticmethod
    def _clear_deferred_secret_autos_for_source(state: GameState, *, source_instance_id: int) -> None:
        state.deferred_secret_autos = [row for row in state.deferred_secret_autos if row.source_instance_id != source_instance_id]

    @staticmethod
    def _promote_deferred_secret_autos_to_public_zone(
        state: GameState,
        *,
        source_instance_id: int,
        source_zone: str,
    ) -> None:
        updated: list[DeferredSecretAuto] = []
        for row in state.deferred_secret_autos:
            if row.source_instance_id != source_instance_id:
                updated.append(row)
                continue
            updated.append(
                DeferredSecretAuto(
                    secret_auto_id=row.secret_auto_id,
                    owner_player_id=row.owner_player_id,
                    source_instance_id=row.source_instance_id,
                    source_card_id=row.source_card_id,
                    source_card_number=row.source_card_number,
                    source_zone=source_zone,
                    trigger=row.trigger,
                    handler_id=row.handler_id,
                    source_skill_text=row.source_skill_text,
                    deferred_turn_number=row.deferred_turn_number,
                    deferred_phase=row.deferred_phase,
                    origin_zone=str(row.origin_zone or row.source_zone),
                    handler_params=dict(row.handler_params),
                    once_per_turn=row.once_per_turn,
                    limit_per_turn=row.limit_per_turn,
                    limit_scope=row.limit_scope,
                )
            )
        state.deferred_secret_autos = updated

    @staticmethod
    def _find_linked_deferred_secret_auto(
        state: GameState,
        *,
        source_instance_id: int,
        trigger: str,
        handler_id: str,
        handler_params: dict[str, int | str | bool],
        source_skill_text: str,
    ) -> DeferredSecretAuto | None:
        return next(
            (
                row
                for row in state.deferred_secret_autos
                if row.source_instance_id == source_instance_id
                and row.trigger == trigger
                and row.handler_id == handler_id
                and dict(row.handler_params) == dict(handler_params)
                and str(row.source_skill_text or "") == str(source_skill_text or "")
            ),
            None,
        )

    @staticmethod
    def _preserve_secret_auto_provenance_on_public_registration(
        row: DeferredSecretAuto,
        *,
        source_zone: str,
    ) -> bool:
        trigger = str(row.trigger or "")
        origin_zone = str(row.origin_zone or row.source_zone)
        current_zone = str(source_zone or "")
        if trigger == "self_played":
            return origin_zone in {"hand", "life", "deck"} and current_zone in {"battle", "unison"}
        return (
            False
        )

    def _record_deferred_secret_auto(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        card: CardInstance,
        source_zone: str,
        trigger: str,
        handler_id: str,
        handler_params: dict[str, int | str | bool],
        source_skill_text: str,
        once_per_turn: bool,
        limit_per_turn: int | None,
        limit_scope: str,
    ) -> None:
        exists = any(
            row.owner_player_id == owner_player_id
            and row.source_instance_id == card.instance_id
            and row.source_zone == source_zone
            and row.trigger == trigger
            and row.handler_id == handler_id
            and dict(row.handler_params) == dict(handler_params)
            and str(row.source_skill_text or "") == str(source_skill_text or "")
            for row in state.deferred_secret_autos
        )
        if exists:
            return
        state.deferred_secret_autos.append(
            DeferredSecretAuto(
                secret_auto_id=state.next_secret_auto_id,
                owner_player_id=owner_player_id,
                source_instance_id=card.instance_id,
                source_card_id=card.card_id,
                source_card_number=str(card.card_number or ""),
                source_zone=source_zone,
                trigger=trigger,
                handler_id=handler_id,
                source_skill_text=str(source_skill_text or ""),
                deferred_turn_number=state.turn_number,
                deferred_phase=state.phase,
                origin_zone=source_zone,
                handler_params=dict(handler_params),
                once_per_turn=bool(once_per_turn),
                limit_per_turn=limit_per_turn,
                limit_scope=str(limit_scope or "card_number"),
            )
        )
        state.next_secret_auto_id += 1

    def _emit_effect_event(
        self,
        state: GameState,
        *,
        name: str,
        actor_player_id: int | None,
        payload: dict[str, int | str | None],
    ) -> None:
        event = EffectEvent(
            event_id=state.next_effect_event_id,
            turn_number=state.turn_number,
            phase=state.phase,
            name=name,
            actor_player_id=actor_player_id,
            payload=dict(payload),
        )
        state.next_effect_event_id += 1
        state.effect_events.append(event)
        self._apply_delayed_union_play_keyword_grants(state, event)
        for reg in state.effect_registry:
            if self._effect_registration_matches_event(reg, event):
                if self._is_registration_temporarily_activation_restricted(state, reg):
                    state.effect_resolutions.append(
                        EffectResolution(
                            effect_id=reg.effect_id,
                            event_id=event.event_id,
                            resolved=False,
                            reason="temporary_skill_activation_restricted",
                        )
                    )
                    state.log.append(
                        "Public effect blocked by temporary activation restriction: "
                        f"effect_id={reg.effect_id} source_instance_id={reg.source_instance_id} "
                        f"trigger={reg.trigger} handler={reg.handler_id}"
                    )
                    self._checkpoint(state, "effect_temporary_skill_activation_restricted")
                    continue
                if self._is_registration_permanently_activation_restricted(state, reg):
                    state.effect_resolutions.append(
                        EffectResolution(
                            effect_id=reg.effect_id,
                            event_id=event.event_id,
                            resolved=False,
                            reason="permanent_skill_activation_restricted",
                        )
                    )
                    state.log.append(
                        "Public effect blocked by permanent activation restriction: "
                        f"effect_id={reg.effect_id} source_instance_id={reg.source_instance_id} "
                        f"trigger={reg.trigger} handler={reg.handler_id}"
                    )
                    self._checkpoint(state, "effect_permanent_skill_activation_restricted")
                    continue
                state.pending_effects.append(PendingEffect(effect_id=reg.effect_id, event_id=event.event_id))
        self._record_secret_auto_opportunities(state, event)
        self._apply_active_low_power_battle_play_hand_warp_penalties(state, event)

    @staticmethod
    def _effect_registration_matches_event(reg: EffectRegistration, event: EffectEvent) -> bool:
        if reg.trigger in {"self_activate_main", "self_activate_battle", "self_activate_extra_from_hand"}:
            if event.name != "skill_activated":
                return False
            expected_skill_kind = {
                "self_activate_main": "activate_main",
                "self_activate_battle": "activate_battle",
                "self_activate_extra_from_hand": "activate_extra_from_hand",
            }[reg.trigger]
            if str(event.payload.get("skill_kind") or "") != expected_skill_kind:
                return False
            selected_effect_id = int(event.payload.get("selected_effect_id") or -1)
            if selected_effect_id > 0 and int(reg.effect_id) != selected_effect_id:
                return False
        return RulesEngine._effect_trigger_matches_event(
            reg.trigger,
            source_instance_id=reg.source_instance_id,
            owner_player_id=reg.owner_player_id,
            event=event,
        )

    @staticmethod
    def _effect_trigger_matches_event(
        trigger: str,
        *,
        source_instance_id: int,
        owner_player_id: int,
        event: EffectEvent,
    ) -> bool:
        if trigger == "self_played":
            if event.name != "card_played":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_placed_in_leader_area":
            if event.name != "card_placed_in_leader_area":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_added_to_z_energy":
            if event.name != "card_added_to_z_energy":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_placed_under_owner_card":
            if event.name != "card_placed_under_card":
                return False
            if int(event.payload.get("source_instance_id") or -1) != source_instance_id:
                return False
            return int(event.payload.get("host_owner_player_id") or -1) == owner_player_id
        if trigger == "self_placed_under_by_union":
            if event.name != "card_placed_under_card":
                return False
            if int(event.payload.get("source_instance_id") or -1) != source_instance_id:
                return False
            if int(event.payload.get("host_owner_player_id") or -1) != owner_player_id:
                return False
            return str(event.payload.get("placed_by") or "").strip().lower() == "union"
        if trigger == "owner_card_placed_under_owner_card":
            if event.name != "card_placed_under_card":
                return False
            return int(event.payload.get("host_owner_player_id") or -1) == owner_player_id
        if trigger == "self_played_using_union":
            if event.name != "card_played":
                return False
            if int(event.payload.get("source_instance_id") or -1) != source_instance_id:
                return False
            return str(event.payload.get("played_via") or "").strip().lower().startswith("union_")
        if trigger == "self_played_using_union_potara":
            if event.name != "card_played":
                return False
            if int(event.payload.get("source_instance_id") or -1) != source_instance_id:
                return False
            return str(event.payload.get("played_via") or "").strip().lower() == "union_potara"
        if trigger == "self_played_using_union_fusion":
            if event.name != "card_played":
                return False
            if int(event.payload.get("source_instance_id") or -1) != source_instance_id:
                return False
            return str(event.payload.get("played_via") or "").strip().lower() == "union_fusion"
        if trigger == "self_played_using_union_absorb":
            if event.name != "card_played":
                return False
            if int(event.payload.get("source_instance_id") or -1) != source_instance_id:
                return False
            return str(event.payload.get("played_via") or "").strip().lower() == "union_absorb"
        if trigger == "self_attacks":
            if event.name != "attack_declared":
                return False
            return int(event.payload.get("attacker_instance_id") or -1) == source_instance_id
        if trigger == "owner_leader_attacks":
            if event.name != "attack_declared":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            return str(event.payload.get("attacker_zone") or "") == "leader"
        if trigger == "self_leader_wished":
            if event.name != "leader_wished":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_leader_wished":
            return event.name == "leader_wished" and event.actor_player_id == owner_player_id
        if trigger == "self_leader_z_awakened":
            if event.name != "leader_z_awakened":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_leader_z_awakened":
            return event.name == "leader_z_awakened" and event.actor_player_id == owner_player_id
        if trigger == "self_union_activated":
            if event.name != "union_activated":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_union_activated":
            return event.name == "union_activated" and event.actor_player_id == owner_player_id
        if trigger == "self_union_absorb_activated":
            if event.name != "union_activated":
                return False
            if str(event.payload.get("union_kind") or "").strip().lower() != "union_absorb":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_union_absorb_activated":
            if event.name != "union_activated":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            return str(event.payload.get("union_kind") or "").strip().lower() == "union_absorb"
        if trigger == "self_union_fusion_activated":
            if event.name != "union_activated":
                return False
            if str(event.payload.get("union_kind") or "").strip().lower() != "union_fusion":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_union_fusion_activated":
            if event.name != "union_activated":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            return str(event.payload.get("union_kind") or "").strip().lower() == "union_fusion"
        if trigger == "self_union_potara_activated":
            if event.name != "union_activated":
                return False
            if str(event.payload.get("union_kind") or "").strip().lower() != "union_potara":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_union_potara_activated":
            if event.name != "union_activated":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            return str(event.payload.get("union_kind") or "").strip().lower() == "union_potara"
        if trigger == "owner_opponent_battle_attacks":
            if event.name != "attack_declared":
                return False
            if event.actor_player_id in {None, owner_player_id}:
                return False
            return str(event.payload.get("attacker_zone") or "") == "battle"
        if trigger == "owner_opponent_card_attacks":
            if event.name != "attack_declared":
                return False
            return event.actor_player_id not in {None, owner_player_id}
        if trigger == "owner_other_battle_played_by_dark_over_realm":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            if str(event.payload.get("played_via") or "").strip().lower() != "dark_over_realm":
                return False
            return int(event.payload.get("source_instance_id") or -1) != source_instance_id
        if trigger == "owner_other_battle_played_by_over_realm":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            if str(event.payload.get("played_via") or "").strip().lower() != "over_realm":
                return False
            return int(event.payload.get("source_instance_id") or -1) != source_instance_id
        if trigger == "owner_other_battle_played":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            return int(event.payload.get("source_instance_id") or -1) != source_instance_id
        if trigger == "owner_other_battle_played_using_union":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            if not str(event.payload.get("played_via") or "").strip().lower().startswith("union_"):
                return False
            return int(event.payload.get("source_instance_id") or -1) != source_instance_id
        if trigger == "owner_other_battle_played_using_union_potara":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            if str(event.payload.get("played_via") or "").strip().lower() != "union_potara":
                return False
            return int(event.payload.get("source_instance_id") or -1) != source_instance_id
        if trigger == "owner_other_battle_played_using_union_fusion":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            if str(event.payload.get("played_via") or "").strip().lower() != "union_fusion":
                return False
            return int(event.payload.get("source_instance_id") or -1) != source_instance_id
        if trigger == "owner_other_battle_played_using_union_absorb":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            if str(event.payload.get("played_via") or "").strip().lower() != "union_absorb":
                return False
            return int(event.payload.get("source_instance_id") or -1) != source_instance_id
        if trigger == "owner_opponent_main_phase_start":
            return event.name == "main_phase_start" and event.actor_player_id not in {None, owner_player_id}
        if trigger == "owner_main_phase_start":
            return event.name == "main_phase_start" and event.actor_player_id == owner_player_id
        if trigger == "self_removed_from_game":
            if event.name != "card_removed_from_game":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_comboed":
            if event.name != "card_comboed":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_card_comboed":
            if event.name != "card_comboed":
                return False
            return event.actor_player_id == owner_player_id
        if trigger == "owner_opponent_card_comboed":
            if event.name != "card_comboed":
                return False
            return event.actor_player_id not in {None, owner_player_id}
        if trigger == "self_or_opponent_battle_played":
            if event.name != "card_played":
                return False
            source_zone = str(event.payload.get("source_zone") or "").strip().lower()
            if event.actor_player_id == owner_player_id:
                return source_zone == "battle" and int(event.payload.get("source_instance_id") or -1) == source_instance_id
            return event.actor_player_id not in {None, owner_player_id} and source_zone == "battle"
        if trigger == "self_in_hand_sent_to_drop_or_warp":
            if event.name not in {"card_placed_into_drop", "card_sent_to_warp"}:
                return False
            if str(event.payload.get("source_zone") or "") != "hand":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_hidden_battle_to_drop":
            if event.name != "card_placed_into_drop":
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            if not bool(event.payload.get("source_hidden_mode") or False):
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_switched_hidden":
            if event.name != "card_switched_hidden_mode":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_switched_revealed":
            if event.name != "card_switched_revealed_mode":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_activate_main":
            if event.name != "skill_activated":
                return False
            if str(event.payload.get("skill_kind") or "") != "activate_main":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_activate_battle":
            if event.name != "skill_activated":
                return False
            if str(event.payload.get("skill_kind") or "") != "activate_battle":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_activate_extra_from_hand":
            if event.name != "skill_activated":
                return False
            if str(event.payload.get("skill_kind") or "") != "activate_extra_from_hand":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_activate_extra_from_hand":
            if event.name != "skill_activated":
                return False
            if str(event.payload.get("skill_kind") or "") != "activate_extra_from_hand":
                return False
            return event.actor_player_id == owner_player_id
        if trigger == "self_koed":
            if event.name != "card_koed":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_battle_played_from_warp":
            if event.name != "card_played":
                return False
            if event.actor_player_id != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            return str(event.payload.get("played_from") or "") == "warp"
        if trigger == "owner_field_extra_placed":
            return event.name == "field_extra_placed"
        if trigger == "self_field_extra_placed":
            if event.name != "field_extra_placed":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_field_extra_placed_into_drop":
            if event.name != "card_placed_into_drop":
                return False
            if int(event.payload.get("owner_player_id") or -1) != owner_player_id:
                return False
            if str(event.payload.get("source_zone") or "").strip().lower() != "battle":
                return False
            keywords = {
                part.strip().lower()
                for part in str(event.payload.get("source_keywords") or "").replace("|", ",").split(",")
                if part.strip()
            }
            return "field" in keywords
        if trigger == "owner_opponent_skill_plays_overcost_battle":
            if event.name != "card_played":
                return False
            if event.actor_player_id in {None, owner_player_id}:
                return False
            if str(event.payload.get("source_zone") or "") != "battle":
                return False
            return str(event.payload.get("played_from") or "").strip().lower() not in {"", "hand"}
        if trigger == "self_comboed_battle_end":
            return event.name == "battle_end"
        if trigger == "self_blocker_activated":
            if event.name != "blocker_activated":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "self_aegis_activated":
            if event.name != "aegis_activated":
                return False
            return int(event.payload.get("source_instance_id") or -1) == source_instance_id
        if trigger == "owner_aegis_activated":
            return event.name == "aegis_activated" and event.actor_player_id == owner_player_id
        if trigger == "turn_start":
            return event.name == "turn_start" and event.actor_player_id == owner_player_id
        if trigger == "turn_end":
            return event.name == "turn_end" and event.actor_player_id == owner_player_id
        return False

    def _record_secret_auto_opportunities(self, state: GameState, event: EffectEvent) -> None:
        created = False
        preblocked = False
        regs_by_id = self._effect_registrations_for_limit_counting(state)
        events_by_id = {evt.event_id: evt for evt in state.effect_events}
        resolved_once_per_turn_counts = self._current_effect_once_per_turn_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        resolved_limit_counts = self._current_effect_limit_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        for row in state.deferred_secret_autos:
            if not self._effect_trigger_matches_event(
                row.trigger,
                source_instance_id=row.source_instance_id,
                owner_player_id=row.owner_player_id,
                event=event,
            ):
                continue
            exists = any(
                opp.secret_auto_id == row.secret_auto_id and opp.event_id == event.event_id
                for opp in state.secret_auto_opportunities
            )
            if exists:
                continue
            temp_reg = EffectRegistration(
                effect_id=-int(row.secret_auto_id),
                owner_player_id=row.owner_player_id,
                source_instance_id=row.source_instance_id,
                source_card_id=row.source_card_id,
                source_zone=row.source_zone,
                trigger=row.trigger,
                handler_id=row.handler_id,
                handler_params=dict(row.handler_params),
                source_skill_text=row.source_skill_text,
                source_card_number=row.source_card_number,
                once_per_turn=row.once_per_turn,
                limit_per_turn=row.limit_per_turn,
                limit_scope=row.limit_scope,
            )
            status = "pending"
            if self._is_registration_temporarily_activation_restricted(state, temp_reg):
                status = "blocked_temporary_restriction"
            elif self._is_registration_permanently_activation_restricted(state, temp_reg):
                status = "blocked_permanent_restriction"
            else:
                once_key = self._effect_once_per_turn_key(temp_reg)
                if once_key is not None and resolved_once_per_turn_counts.get(once_key, 0) >= 1:
                    status = "blocked_once_per_turn"
                else:
                    limit_key = self._effect_limit_key(temp_reg)
                    if limit_key is not None and resolved_limit_counts.get(limit_key, 0) >= int(temp_reg.limit_per_turn or 0):
                        status = "blocked_limit_per_turn"
            state.secret_auto_opportunities.append(
                SecretAutoOpportunity(
                    opportunity_id=state.next_secret_auto_opportunity_id,
                    secret_auto_id=row.secret_auto_id,
                    owner_player_id=row.owner_player_id,
                    source_instance_id=row.source_instance_id,
                    source_card_id=row.source_card_id,
                    source_card_number=row.source_card_number,
                    source_zone=row.source_zone,
                    trigger=row.trigger,
                    handler_id=row.handler_id,
                    source_skill_text=row.source_skill_text,
                    event_id=event.event_id,
                    event_name=event.name,
                    created_turn_number=state.turn_number,
                    created_phase=state.phase,
                    origin_zone=str(row.origin_zone or row.source_zone),
                    handler_params=dict(row.handler_params),
                    once_per_turn=row.once_per_turn,
                    limit_per_turn=row.limit_per_turn,
                    limit_scope=row.limit_scope,
                    status=status,
                    preblocked=(status != "pending"),
                )
            )
            state.next_secret_auto_opportunity_id += 1
            if status == "pending":
                state.log.append(
                    "Secret-area auto opportunity created: "
                    f"source_instance_id={row.source_instance_id} event_id={event.event_id} trigger={row.trigger}"
                )
            else:
                preblocked = True
                state.log.append(
                    "Secret-area auto opportunity preblocked: "
                    f"source_instance_id={row.source_instance_id} event_id={event.event_id} trigger={row.trigger} status={status}"
                )
            created = True
        if created:
            self._checkpoint(state, "secret_auto_opportunity_created")
        if preblocked:
            self._checkpoint(state, "secret_auto_opportunity_preblocked")

    def _apply_active_low_power_battle_play_hand_warp_penalties(self, state: GameState, event: EffectEvent) -> None:
        if event.name != "card_played":
            return
        played_player_id = event.actor_player_id
        if played_player_id is None:
            return
        if str(event.payload.get("source_zone") or "").strip().lower() != "battle":
            return
        penalties = [
            row
            for row in state.low_power_battle_play_hand_warp_penalties
            if int(row.affected_player_id) == int(played_player_id)
        ]
        if not penalties:
            return
        player = state.players.get(played_player_id)
        if player is None:
            return
        source_instance_id = int(event.payload.get("source_instance_id") or -1)
        if source_instance_id <= 0:
            return
        played_card = next((card for card in player.battle_area if int(card.instance_id) == source_instance_id), None)
        if played_card is None:
            return
        applied = False
        for row in penalties:
            if int(getattr(played_card, "power", 0) or 0) > int(row.max_power):
                continue
            moved = 0
            while moved < int(row.hand_to_warp) and player.hand:
                card = player.hand.pop(0)
                self._append_to_owner_warp(state, owner_player_id=played_player_id, card=card, source_zone="hand")
                moved += 1
            if moved > 0:
                applied = True
        if applied:
            self._checkpoint(state, "low_power_battle_play_hand_warp_penalty_applied")

    def _reset_once_per_turn_effect_counters(self, state: GameState, *, player_id: int) -> None:
        updated: list[EffectRegistration] = []
        for reg in state.effect_registry:
            if reg.owner_player_id == player_id and reg.triggers_this_turn != 0:
                updated.append(
                    EffectRegistration(
                        effect_id=reg.effect_id,
                        owner_player_id=reg.owner_player_id,
                        source_instance_id=reg.source_instance_id,
                        source_card_id=reg.source_card_id,
                        source_zone=reg.source_zone,
                        trigger=reg.trigger,
                        handler_id=reg.handler_id,
                        handler_params=dict(reg.handler_params),
                        source_card_number=reg.source_card_number,
                        once_per_turn=reg.once_per_turn,
                        limit_per_turn=reg.limit_per_turn,
                        limit_scope=reg.limit_scope,
                        triggers_this_turn=0,
                    )
                )
            else:
                updated.append(reg)
        state.effect_registry = updated

    @staticmethod
    def _resolve_effect_limit_per_turn(handler_params: dict[str, int | str | bool]) -> int | None:
        raw = handler_params.get("limit_per_turn")
        return int(raw) if isinstance(raw, int) and raw > 0 else None

    @staticmethod
    def _effect_once_per_turn_key(reg: EffectRegistration) -> tuple[object, ...] | None:
        if not reg.once_per_turn:
            return None
        return (
            reg.owner_player_id,
            reg.source_instance_id,
            reg.trigger,
            reg.handler_id,
            tuple(sorted(reg.handler_params.items())),
        )

    def _current_effect_once_per_turn_counts(
        self,
        state: GameState,
        *,
        regs_by_id: dict[int, EffectRegistration],
        events_by_id: dict[int, EffectEvent],
    ) -> dict[tuple[object, ...], int]:
        counts: dict[tuple[object, ...], int] = {}
        for row in state.effect_resolutions:
            if not row.resolved:
                continue
            reg = regs_by_id.get(row.effect_id)
            evt = events_by_id.get(row.event_id)
            if reg is None or evt is None or evt.turn_number != state.turn_number:
                continue
            key = self._effect_once_per_turn_key(reg)
            if key is None:
                continue
            counts[key] = counts.get(key, 0) + 1
        return counts

    @staticmethod
    def _effect_limit_source_group(reg: EffectRegistration) -> str:
        scope = str(reg.limit_scope or "card_number").strip() or "card_number"
        if scope == "source_instance":
            return f"instance:{reg.source_instance_id}"
        if scope == "card_id":
            return f"card_id:{reg.source_card_id}"
        return str(reg.source_card_number or f"card_id:{reg.source_card_id}")

    @staticmethod
    def _effect_limit_key(reg: EffectRegistration) -> tuple[object, ...] | None:
        if reg.limit_per_turn is None or reg.limit_per_turn <= 0:
            return None
        scope = str(reg.limit_scope or "card_number").strip() or "card_number"
        source_group = RulesEngine._effect_limit_source_group(reg)
        return (
            reg.owner_player_id,
            scope,
            source_group,
            reg.trigger,
            reg.handler_id,
            tuple(sorted(reg.handler_params.items())),
        )

    def _current_effect_limit_counts(
        self,
        state: GameState,
        *,
        regs_by_id: dict[int, EffectRegistration],
        events_by_id: dict[int, EffectEvent],
    ) -> dict[tuple[object, ...], int]:
        counts: dict[tuple[object, ...], int] = {}
        for row in state.effect_resolutions:
            if not row.resolved:
                continue
            reg = regs_by_id.get(row.effect_id)
            evt = events_by_id.get(row.event_id)
            if reg is None or evt is None or evt.turn_number != state.turn_number:
                continue
            key = self._effect_limit_key(reg)
            if key is None:
                continue
            counts[key] = counts.get(key, 0) + 1
        return counts

    def _effect_registrations_for_limit_counting(self, state: GameState) -> dict[int, EffectRegistration]:
        regs_by_id = {reg.effect_id: reg for reg in state.effect_registry}
        for opportunity in state.secret_auto_opportunities:
            if opportunity.status != "declared":
                continue
            effect_id = -int(opportunity.secret_auto_id)
            regs_by_id[effect_id] = EffectRegistration(
                effect_id=effect_id,
                owner_player_id=opportunity.owner_player_id,
                source_instance_id=opportunity.source_instance_id,
                source_card_id=opportunity.source_card_id,
                source_zone=opportunity.source_zone,
                trigger=opportunity.trigger,
                handler_id=opportunity.handler_id,
                handler_params=dict(opportunity.handler_params),
                source_card_number=opportunity.source_card_number,
                once_per_turn=opportunity.once_per_turn,
                limit_per_turn=opportunity.limit_per_turn,
                limit_scope=opportunity.limit_scope,
            )
        return regs_by_id

    def _pop_next_pending_effect(self, state: GameState) -> PendingEffect | None:
        if not state.pending_effects:
            return None
        regs_by_id = {reg.effect_id: reg for reg in state.effect_registry}
        owner_order = [state.active_player, self._opponent_of(state.active_player)]
        for owner_id in owner_order:
            matching: list[tuple[int, PendingEffect]] = []
            for idx, entry in enumerate(state.pending_effects):
                reg = regs_by_id.get(entry.effect_id)
                if reg is not None and reg.owner_player_id == owner_id:
                    matching.append((idx, entry))
            if matching:
                selected_idx = min(matching, key=lambda item: (int(item[1].event_id), int(item[1].effect_id), int(item[0])))[0]
                return state.pending_effects.pop(selected_idx)
        return state.pending_effects.pop(0)

    def _resolve_pending_effects(self, state: GameState) -> None:
        if not state.pending_effects:
            return
        regs_by_id = self._effect_registrations_for_limit_counting(state)
        events_by_id = {evt.event_id: evt for evt in state.effect_events}
        resolved_once_per_turn_counts = self._current_effect_once_per_turn_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        resolved_limit_counts = self._current_effect_limit_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        while state.pending_effects:
            entry = self._pop_next_pending_effect(state)
            if entry is None:
                break
            regs_by_id = self._effect_registrations_for_limit_counting(state)
            events_by_id = {evt.event_id: evt for evt in state.effect_events}
            reg = regs_by_id.get(entry.effect_id)
            evt = events_by_id.get(entry.event_id)
            if reg is None or evt is None:
                state.effect_resolutions.append(
                    EffectResolution(effect_id=entry.effect_id, event_id=entry.event_id, resolved=False, reason="missing_context")
                )
                continue
            once_key = self._effect_once_per_turn_key(reg)
            if once_key is not None and resolved_once_per_turn_counts.get(once_key, 0) >= 1:
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="once_per_turn_used")
                )
                state.log.append(
                    "Public effect blocked by once-per-turn: "
                    f"effect_id={reg.effect_id} source_instance_id={reg.source_instance_id} "
                    f"trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_once_per_turn_blocked")
                continue
            limit_key = self._effect_limit_key(reg)
            if limit_key is not None and resolved_limit_counts.get(limit_key, 0) >= int(reg.limit_per_turn or 0):
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="limit_per_turn_used")
                )
                state.log.append(
                    "Public effect blocked by limit: "
                    f"effect_id={reg.effect_id} source_instance_id={reg.source_instance_id} "
                    f"limit_scope={reg.limit_scope} limit_per_turn={reg.limit_per_turn} "
                    f"trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_limit_per_turn_blocked")
                continue
            if not self._is_effect_source_active(state, reg):
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="source_missing")
                )
                continue
            handler = self._effect_handlers.get(reg.handler_id)
            if handler is None:
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="missing_handler")
                )
                continue
            handler(state, evt, reg)
            self._apply_post_resolution_registration_effects(state, evt, reg)
            next_reg = EffectRegistration(
                effect_id=reg.effect_id,
                owner_player_id=reg.owner_player_id,
                source_instance_id=reg.source_instance_id,
                source_card_id=reg.source_card_id,
                source_zone=reg.source_zone,
                trigger=reg.trigger,
                handler_id=reg.handler_id,
                handler_params=dict(reg.handler_params),
                source_card_number=reg.source_card_number,
                once_per_turn=reg.once_per_turn,
                limit_per_turn=reg.limit_per_turn,
                limit_scope=reg.limit_scope,
                triggers_this_turn=reg.triggers_this_turn + 1,
            )
            state.effect_registry = [next_reg if item.effect_id == reg.effect_id else item for item in state.effect_registry]
            if once_key is not None:
                resolved_once_per_turn_counts[once_key] = resolved_once_per_turn_counts.get(once_key, 0) + 1
            if limit_key is not None:
                resolved_limit_counts[limit_key] = resolved_limit_counts.get(limit_key, 0) + 1
            state.effect_resolutions.append(
                EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=True, reason="ok")
            )

    @staticmethod
    def _evaluate_continuous_effects(_state: GameState) -> None:
        # Phase 4.1: continuous/permanent effects will be evaluated here without entering pending status.
        return

    @staticmethod
    def _handle_noop_effect(state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        state.log.append(
            f"Effect resolved: effect_id={reg.effect_id} source={reg.source_instance_id} trigger={reg.trigger} event={event.name}"
        )

    def _handle_auto_draw_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_on_play")

    def _handle_auto_draw_on_attack(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "attack_declared":
            return
        self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_on_attack")

    def _handle_auto_draw_n(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name not in {"card_played", "attack_declared", "card_comboed", "skill_activated", "turn_start", "turn_end", "main_phase_start", "aegis_activated", "leader_wished", "leader_z_awakened", "union_activated", "card_added_to_z_energy"}:
            return
        if not self._effect_requirements_met(state, reg):
            return
        if reg.trigger == "owner_card_comboed":
            owner_combo_match = self._match_owner_combo_event(state, event, reg)
            if owner_combo_match is None:
                return
            owner, _live_combo_card, _combo_probe = owner_combo_match
            if not self._pay_owner_combo_skill_cost_if_needed(state, event, reg, owner):
                return
        if event.name == "main_phase_start":
            if not self._can_pay_main_phase_auto_costs(state, reg):
                return
            if not self._pay_main_phase_auto_costs(state, reg):
                return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        if amount <= 0:
            return
        for _ in range(amount):
            self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_n")

    def _handle_auto_draw_n_switch_up_to_n_owner_leader_and_energy_active_and_grant_owner_leader_keyword_for_turn(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "main_phase_start":
            return
        if not self._effect_requirements_met(state, reg):
            return
        if not self._can_pay_main_phase_auto_costs(state, reg):
            return
        if not self._pay_main_phase_auto_costs(state, reg):
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_leader_targets = self._resolve_effect_int_param(state, reg, "max_leader_targets", default=1)
        if max_leader_targets > 0:
            owner.leader_area.resting = False
        max_energy_targets = self._resolve_effect_int_param(state, reg, "max_energy_targets", default=1)
        if max_energy_targets > 0:
            activated = 0
            for card in owner.energy:
                if activated >= max_energy_targets:
                    break
                if not card.resting:
                    continue
                card.resting = False
                activated += 1
        grant_keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
        if grant_keyword:
            self._append_temporary_keyword(owner.leader_area, grant_keyword, duration="turn")
        self._checkpoint(state, "effect_auto_draw_n_switch_up_to_n_owner_leader_and_energy_active_and_grant_owner_leader_keyword_for_turn")

    def _handle_auto_switch_up_to_n_opponent_energy_rest_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "owner_aegis_activated":
            if event.name != "aegis_activated" or event.actor_player_id != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        candidates = [card for card in opponent.energy if not card.resting]
        if not candidates:
            return
        policy = str(reg.handler_params.get("target_policy", "first"))
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, policy)
        if not indexes:
            return
        for idx in indexes:
            candidates[idx].resting = True
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_energy_rest_on_aegis")

    def _handle_auto_draw_n_switch_self_active_and_switch_up_to_n_opponent_board_rest_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is not None and source.resting and self._can_switch_card_to_active(source):
            source.resting = False
        targets = self._select_opponent_battle_or_unison_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
            prefer_attacker=bool(reg.handler_params.get("prefer_attacker", False)),
        )
        for target in targets:
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
            else:
                self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_draw_n_switch_self_active_and_switch_up_to_n_opponent_board_rest_on_aegis")

    def _handle_auto_optional_discard_play_up_to_n_from_owner_drop_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "owner_aegis_activated":
            if event.name != "aegis_activated" or event.actor_player_id != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.drop:
            return
        discard_before = self._resolve_effect_int_param(state, reg, "discard_from_hand_before", default=1)
        if discard_before > 0:
            if len(owner.hand) < discard_before:
                return
            for _ in range(discard_before):
                discarded = owner.hand.pop(0)
                owner.drop.append(discarded)
                self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=discarded, source_zone="hand")
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_card_types", reg.handler_params.get("required_card_type", ""))).replace("|", ",").split(",")
            if part.strip()
        }
        requires_no_keywords = bool(reg.handler_params.get("requires_no_keywords", False))
        rest_mode = bool(reg.handler_params.get("rest_mode", False))
        negate_skills = bool(reg.handler_params.get("negate_skills", False))
        candidates: list[tuple[int, CardInstance]] = []
        for idx, card in enumerate(owner.drop):
            if max_cost >= 0 and (card.energy_cost is None or int(card.energy_cost) > max_cost):
                continue
            if required_card_types and str(card.card_type or "").upper() not in required_card_types:
                continue
            if requires_no_keywords and any(str(keyword).strip() for keyword in (card.keywords or ())):
                continue
            if not self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
                required_card_types=required_card_types or None,
            ):
                continue
            candidates.append((idx, card))
        if not candidates:
            return
        chosen_indexes = self._choose_effect_target_indexes(
            state,
            reg,
            [card for _, card in candidates],
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not chosen_indexes:
            return
        removed = 0
        for chosen in chosen_indexes:
            source_idx, _ = candidates[chosen]
            card = owner.drop.pop(source_idx - removed)
            removed += 1
            card.resting = rest_mode
            if negate_skills:
                card.keywords = ()
                card.counter_modes = ()
                card.has_counter = False
                card.has_counter_attack = False
                card.has_counter_battle_card_attack = False
                card.has_counter_play = False
                card.has_counter_counter = False
                card.has_activate_main = False
                card.has_activate_battle = False
                card.has_auto = False
                card.has_permanent = False
                card.has_draw = False
                card.max_draw = None
                card.auto_once_per_turn = False
                card.auto_draw_on_play = False
                card.auto_draw_on_attack = False
                card.has_barrier = False
            target_zone = "battle"
            if "UNISON" in str(card.card_type or "").upper():
                target_zone = "unison"
                self._replace_owner_unison_if_needed(state, owner)
                owner.unison_area.append(card)
            else:
                owner.battle_area.append(card)
            if not negate_skills:
                self._register_card_effects(state, player_id=reg.owner_player_id, source_zone=target_zone, card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": target_zone,
                    "played_from": "drop",
                },
            )
        self._checkpoint(state, "effect_auto_optional_discard_play_up_to_n_from_owner_drop_on_aegis")

    def _handle_auto_place_top_n_from_opponent_deck_into_drop_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "owner_aegis_activated":
            if event.name != "aegis_activated" or event.actor_player_id != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None or not opponent.deck:
            return
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_no_other_owner_traits", reg.handler_params.get("required_traits", ""))).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_no_other_owner_characters", reg.handler_params.get("required_characters", ""))).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(
            reg.handler_params.get("required_no_other_owner_name_contains", reg.handler_params.get("required_name_contains", ""))
        ).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_no_other_owner_card_types", "BATTLE")).replace("|", ",").split(",")
            if part.strip()
        }
        if required_traits or required_characters or required_name_contains:
            for card in owner.battle_area:
                if card.instance_id == reg.source_instance_id:
                    continue
                if self._card_matches_effect_filters(
                    card,
                    allowed_colors=set(),
                    required_traits=required_traits,
                    required_characters=required_characters,
                    required_name_contains=required_name_contains,
                    required_card_types=required_card_types or None,
                ):
                    return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        removed = 0
        while removed < amount and opponent.deck:
            card_id = opponent.deck.pop(0)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=opponent.player_id)
            state.next_instance_id += 1
            opponent.drop.append(card)
            self._emit_card_placed_into_drop(state, owner_player_id=opponent.player_id, card=card, source_zone="deck")
            removed += 1
        if removed:
            self._checkpoint(state, "effect_auto_place_top_n_from_opponent_deck_into_drop_on_aegis")

    def _handle_auto_pay_life_on_attack_gain_power_and_keyword_for_turn(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        life_to_hand = self._resolve_effect_int_param(state, reg, "life_to_hand", default=1)
        if life_to_hand > 0:
            if len(owner.life) < life_to_hand:
                return
            for _ in range(life_to_hand):
                owner.hand.append(owner.life.pop(0))
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if delta != 0:
            self._apply_temporary_power_delta(state, card=source, delta=delta, reason="effect_self_attack_buff")
        grant_keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
        if grant_keyword and not self._card_has_keyword(source, grant_keyword):
            source.temporary_keywords = tuple(list(source.temporary_keywords) + [grant_keyword])
        self._checkpoint(state, "effect_auto_pay_life_on_attack_gain_power_and_keyword_for_turn")

    def _handle_auto_add_up_to_n_from_owner_hand_to_life_on_owner_leader_attack(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if str(event.payload.get("attacker_zone") or "") != "leader":
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.hand:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        if amount <= 0:
            return
        raw_colors = str(reg.handler_params.get("allowed_colors", "")).strip().lower()
        allowed_colors = {c.strip() for c in raw_colors.replace("/", ",").replace("|", ",").split(",") if c.strip()}
        chosen_indexes: list[int] = []
        for i, c in enumerate(owner.hand):
            if allowed_colors:
                colors = {p.strip().lower() for p in str(c.color or "").replace("/", ",").split(",") if p.strip()}
                if colors and colors.isdisjoint(allowed_colors):
                    continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= amount:
                break
        if not chosen_indexes:
            return
        removed = 0
        for idx in chosen_indexes:
            owner.life.append(owner.hand.pop(idx - removed))
            removed += 1
        self._checkpoint(state, "effect_auto_add_up_to_n_from_owner_hand_to_life_on_owner_leader_attack")

    def _handle_auto_add_up_to_n_from_owner_hand_to_life_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.hand:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        if amount <= 0:
            return
        raw_colors = str(reg.handler_params.get("allowed_colors", "")).strip().lower()
        allowed_colors = {c.strip() for c in raw_colors.replace("/", ",").replace("|", ",").split(",") if c.strip()}
        chosen_indexes: list[int] = []
        for i, c in enumerate(owner.hand):
            if allowed_colors:
                colors = {p.strip().lower() for p in str(c.color or "").replace("/", ",").split(",") if p.strip()}
                if colors and colors.isdisjoint(allowed_colors):
                    continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= amount:
                break
        if not chosen_indexes:
            return
        removed = 0
        for idx in chosen_indexes:
            owner.life.append(owner.hand.pop(idx - removed))
            removed += 1
        self._checkpoint(state, "effect_auto_add_up_to_n_from_owner_hand_to_life_on_play")

    def _handle_auto_gain_wormhole_on_owner_black_battle_played_from_warp(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if str(event.payload.get("source_zone") or "") != "battle":
            return
        if str(event.payload.get("played_from") or "") != "warp":
            return
        source_card_id = int(event.payload.get("source_card_id") or -1)
        if source_card_id <= 0:
            return
        runtime = self._resolve_card_runtime_data(source_card_id)
        if (runtime.color or "").strip().lower() != "black":
            return
        state.log.append(f"effect:wormhole_gain:source={reg.source_instance_id}")
        self._checkpoint(state, "effect_auto_gain_wormhole_on_owner_black_battle_played_from_warp")

    def _handle_auto_place_up_to_n_from_owner_deck_to_destination_zone(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name not in {"card_placed_into_drop", "card_sent_to_warp"}:
            return
        if not self._effect_requirements_met(state, reg):
            return
        if str(event.payload.get("source_zone") or "") != "hand":
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.deck:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        max_power = self._resolve_effect_int_param(state, reg, "max_power", default=-1)
        raw_colors = str(reg.handler_params.get("allowed_colors", "")).strip().lower()
        allowed_colors = {c.strip() for c in raw_colors.replace("|", ",").replace("/", ",").split(",") if c.strip()}
        raw_traits = str(reg.handler_params.get("required_traits", "")).strip().lower()
        required_traits = {t.strip() for t in raw_traits.replace("|", ",").split(",") if t.strip()}
        raw_characters = str(reg.handler_params.get("required_characters", "")).strip().lower()
        required_characters = {t.strip() for t in raw_characters.replace("|", ",").split(",") if t.strip()}
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_type = str(reg.handler_params.get("required_card_type", "")).strip().upper()
        chosen_indexes: list[int] = []
        for i, deck_card in enumerate(owner.deck):
            deck_card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
            runtime = self._resolve_card_runtime_data(deck_card_id)
            if required_type and required_type not in (runtime.card_type or "").upper():
                continue
            if max_power >= 0 and (runtime.power is None or runtime.power > max_power):
                continue
            temp_card = CardInstance(
                instance_id=0,
                card_id=deck_card_id,
                owner_id=reg.owner_player_id,
                card_type=runtime.card_type,
                color=runtime.color,
                power=runtime.power,
                traits=runtime.traits,
                characters=runtime.characters,
            )
            if not self._card_matches_effect_filters(
                temp_card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
            ):
                continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= max_targets:
                break
        if not chosen_indexes:
            return
        destination_is_warp = bool(reg.handler_params.get("mirror_destination_zone", False)) and event.name == "card_sent_to_warp"
        removed = 0
        for idx in chosen_indexes:
            deck_card = owner.deck.pop(idx - removed)
            removed += 1
            card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            if destination_is_warp:
                self._append_to_owner_warp(state, owner_player_id=reg.owner_player_id, card=card, source_zone="deck")
            else:
                owner.drop.append(card)
                self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=card, source_zone="deck")
        self._checkpoint(state, "effect_auto_place_up_to_n_from_owner_deck_to_destination_zone")

    def _handle_auto_play_self_from_drop_on_hand_drop(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_placed_into_drop":
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_destination_zone = str(reg.handler_params.get("required_destination_zone", "")).strip().lower()
        if required_destination_zone and required_destination_zone != "drop":
            return
        required_drop_causes_raw = str(reg.handler_params.get("required_drop_causes", "")).strip().lower()
        if required_drop_causes_raw:
            required_drop_causes = {
                part.strip()
                for part in required_drop_causes_raw.replace("|", ",").split(",")
                if part.strip()
            }
            drop_cause = str(event.payload.get("drop_cause") or "").strip().lower()
            if drop_cause not in required_drop_causes:
                return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        idx = next((i for i, card in enumerate(owner.drop) if card.instance_id == reg.source_instance_id), None)
        if idx is None:
            return
        played = owner.drop.pop(idx)
        played.resting = bool(reg.handler_params.get("resting", False))
        owner.battle_area.append(played)
        self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=played)
        self._emit_effect_event(
            state,
            name="card_played",
            actor_player_id=reg.owner_player_id,
            payload={
                "source_instance_id": played.instance_id,
                "source_card_id": played.card_id,
                "source_zone": "battle",
                "played_from": "drop",
            },
        )
        self._checkpoint(state, "effect_auto_play_self_from_drop_on_hand_drop")

    def _handle_auto_play_self_from_hand_on_owner_field_extra_to_drop_switch_up_to_n_opponent_board_rest(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_placed_into_drop":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        idx = next((i for i, card in enumerate(owner.hand) if card.instance_id == reg.source_instance_id), None)
        if idx is None:
            return
        played = owner.hand.pop(idx)
        played.resting = bool(reg.handler_params.get("resting", False))
        owner.battle_area.append(played)
        self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=played)
        self._emit_effect_event(
            state,
            name="card_played",
            actor_player_id=reg.owner_player_id,
            payload={
                "source_instance_id": played.instance_id,
                "source_card_id": played.card_id,
                "source_zone": "battle",
                "played_from": "hand",
            },
        )
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets > 0:
            opponent_id = self._opponent_of(reg.owner_player_id)
            opponent = state.players.get(opponent_id)
            if opponent is not None:
                candidates: list[CardInstance] = [c for c in opponent.battle_area if not c.hidden_mode]
                candidates.extend(opponent.unison_area)
                if not bool(reg.handler_params.get("ignores_barrier", False)):
                    candidates = [c for c in candidates if not self._card_currently_has_barrier(c)]
                policy = str(reg.handler_params.get("target_policy", "first"))
                indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, policy) if candidates else []
                for target_idx in indexes:
                    target = candidates[target_idx]
                    if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                        target.resting = True
                    else:
                        self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_play_self_from_hand_on_owner_field_extra_to_drop_switch_up_to_n_opponent_board_rest")

    def _handle_auto_rest_owner_battle_on_self_blocker_activated_switch_self_active(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "blocker_activated":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "rest_owner_battle_count", default=1)
        if max_targets <= 0:
            return
        candidates = [card for card in owner.battle_area if card.instance_id != source.instance_id]
        candidates.extend(card for card in owner.battle_area if card.instance_id == source.instance_id)
        if not candidates:
            return
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, str(reg.handler_params.get("target_policy", "first")))
        if not indexes:
            return
        for idx in indexes:
            candidates[idx].resting = True
        if self._can_switch_card_to_active(source):
            source.resting = False
        self._checkpoint(state, "effect_auto_rest_owner_battle_on_self_blocker_activated_switch_self_active")

    def _handle_auto_add_up_to_n_matching_from_owner_energy_to_hand_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        allowed_colors = {part.strip().lower() for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",") if part.strip()}
        required_traits = {part.strip().lower() for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",") if part.strip()}
        required_characters = {part.strip().lower() for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",") if part.strip()}
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        candidates: list[tuple[int, CardInstance]] = []
        for idx, card in enumerate(owner.energy):
            if not self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
            ):
                continue
            candidates.append((idx, card))
        if not candidates:
            return
        chosen_indexes = self._choose_effect_target_indexes(
            state,
            reg,
            [card for _, card in candidates],
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not chosen_indexes:
            return
        removed = 0
        for chosen in chosen_indexes:
            source_idx, card = candidates[chosen]
            owner.hand.append(owner.energy.pop(source_idx - removed))
            removed += 1
        self._checkpoint(state, "effect_auto_add_up_to_n_matching_from_owner_energy_to_hand_on_attack")

    def _resolve_auto_combo_up_to_n_from_owner_zone(
        self,
        state: GameState,
        reg: EffectRegistration,
        *,
        checkpoint_name: str,
    ) -> None:
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source_zone = str(reg.handler_params.get("source_zone", "drop")).strip().lower()
        if source_zone == "warp":
            source_cards = owner.warp
        else:
            source_cards = owner.drop
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_card_type = str(reg.handler_params.get("required_card_type", "")).strip().upper()
        exact_combo_power = self._resolve_effect_int_param(state, reg, "exact_combo_power", default=-1)
        require_mono_color = bool(reg.handler_params.get("require_mono_color", False))
        exclude_super_combo = bool(reg.handler_params.get("exclude_super_combo", False))
        candidates: list[tuple[int, CardInstance]] = []
        for idx, card in enumerate(source_cards):
            if required_card_type and str(getattr(card, "card_type", "")).upper() != required_card_type:
                continue
            if exact_combo_power >= 0 and int(getattr(card, "combo_power", -1) or -1) != exact_combo_power:
                continue
            if require_mono_color:
                raw_colors = [part.strip().lower() for part in str(card.color or "").replace("/", ",").split(",") if part.strip()]
                if len(set(raw_colors)) != 1:
                    continue
            if exclude_super_combo and bool(getattr(card, "has_super_combo", False)):
                continue
            if not self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
            ):
                continue
            candidates.append((idx, card))
        if not candidates:
            return
        chosen_indexes = self._choose_effect_target_indexes(
            state,
            reg,
            [card for _, card in candidates],
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not chosen_indexes:
            return
        removed = 0
        for chosen in chosen_indexes:
            source_idx, _ = candidates[chosen]
            combo_card = source_cards.pop(source_idx - removed)
            removed += 1
            if bool(reg.handler_params.get("negate_skills", False)):
                combo_card.temporary_skills_negated = True
            owner.combo_area.append(combo_card)
            self._emit_effect_event(
                state,
                name="card_comboed",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": combo_card.instance_id,
                    "source_card_id": combo_card.card_id,
                    "source_zone": "combo",
                    "comboed_from": source_zone,
                },
            )
        self._checkpoint(state, checkpoint_name)

    def _handle_auto_combo_up_to_n_from_owner_zone_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        self._resolve_auto_combo_up_to_n_from_owner_zone(
            state,
            reg,
            checkpoint_name="effect_auto_combo_up_to_n_from_owner_zone_on_attack",
        )

    def _handle_auto_combo_up_to_n_named_from_under_named_host_on_attack_then_draw_n_and_gain_keyword_for_battle(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        host_name_contains = str(reg.handler_params.get("host_name_contains", "")).strip().upper()
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        if not host_name_contains or not required_name_contains:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        host = next(
            (
                card
                for card in owner.battle_area
                if host_name_contains
                in str(self._resolve_card_runtime_data(card.card_id).card_name or card.card_name or "").upper()
            ),
            None,
        )
        if host is None or not tuple(getattr(host, "stacked_card_ids", ())):
            return
        candidates: list[tuple[int, int]] = []
        for idx, card_id in enumerate(tuple(host.stacked_card_ids)):
            runtime = self._resolve_card_runtime_data(int(card_id))
            runtime_name = str(runtime.card_name or "").upper()
            if required_name_contains not in runtime_name:
                continue
            candidates.append((idx, int(card_id)))
        if not candidates:
            return
        chosen_indexes = self._choose_effect_target_indexes(
            state,
            reg,
            [
                self._create_card_instance(
                    next_instance_id=-(idx + 1),
                    card_id=card_id,
                    owner_id=reg.owner_player_id,
                )
                for idx, card_id in candidates
            ],
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not chosen_indexes:
            return
        stacked_ids = list(host.stacked_card_ids)
        removed = 0
        moved_any = False
        for chosen in chosen_indexes:
            source_idx, card_id = candidates[chosen]
            actual_idx = source_idx - removed
            if not (0 <= actual_idx < len(stacked_ids)):
                continue
            stacked_ids.pop(actual_idx)
            removed += 1
            combo_card = self._create_card_instance(
                next_instance_id=state.next_instance_id,
                card_id=card_id,
                owner_id=reg.owner_player_id,
            )
            state.next_instance_id += 1
            combo_card.comboed_from = "under"
            owner.combo_area.append(combo_card)
            self._emit_effect_event(
                state,
                name="card_comboed",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": combo_card.instance_id,
                    "source_card_id": combo_card.card_id,
                    "source_zone": "combo",
                    "comboed_from": "under",
                },
            )
            moved_any = True
        if not moved_any:
            return
        host.stacked_card_ids = tuple(stacked_ids)
        amount = self._resolve_effect_int_param(state, reg, "amount", default=0)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is not None:
            grant_keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
            if grant_keyword:
                self._append_temporary_keyword(source, grant_keyword, duration="battle")
        self._checkpoint(
            state,
            "effect_auto_combo_up_to_n_named_from_under_named_host_on_attack_then_draw_n_and_gain_keyword_for_battle",
        )

    def _handle_auto_combo_up_to_n_from_owner_zone_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "owner_aegis_activated":
            if event.name != "aegis_activated" or event.actor_player_id != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        self._resolve_auto_combo_up_to_n_from_owner_zone(
            state,
            reg,
            checkpoint_name="effect_auto_combo_up_to_n_from_owner_zone_on_aegis",
        )

    def _handle_auto_pay_life_bottom_deck_play_self_from_drop_or_warp_negate_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None or reg.source_zone not in {"drop", "warp"}:
            return
        life_to_hand = self._resolve_effect_int_param(state, reg, "life_to_hand", default=0)
        if life_to_hand > 0 and len(owner.life) < life_to_hand:
            return
        bottom_deck_from_hand = self._resolve_effect_int_param(state, reg, "bottom_deck_from_hand", default=0)
        if bottom_deck_from_hand > 0 and len(owner.hand) < bottom_deck_from_hand:
            return
        for _ in range(life_to_hand):
            owner.hand.append(owner.life.pop(0))
        for _ in range(bottom_deck_from_hand):
            owner.deck.append(owner.hand.pop(0).card_id)
        zone_cards = owner.drop if reg.source_zone == "drop" else owner.warp
        idx = next((i for i, card in enumerate(zone_cards) if card.instance_id == reg.source_instance_id), None)
        if idx is None:
            return
        played = zone_cards.pop(idx)
        played.resting = bool(reg.handler_params.get("resting", False))
        owner.battle_area.append(played)
        self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=played)
        self._emit_effect_event(
            state,
            name="card_played",
            actor_player_id=reg.owner_player_id,
            payload={
                "source_instance_id": played.instance_id,
                "source_card_id": played.card_id,
                "source_zone": "battle",
                "played_from": reg.source_zone,
            },
        )
        if bool(reg.handler_params.get("negate_attack", False)):
            state.counter_window = None
            state.attack_context = None
            state.battle_step = BattleStep.BATTLE_END
            self._checkpoint(state, "battle_end_step")
        self._checkpoint(state, "effect_auto_pay_life_bottom_deck_play_self_from_drop_or_warp_negate_attack")

    def _handle_auto_place_top_n_from_owner_deck_into_drop(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if reg.trigger == "self_removed_from_game":
            if event.name != "card_removed_from_game":
                return
        elif event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.deck:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        removed = 0
        while removed < amount and owner.deck:
            card_id = owner.deck.pop(0)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            owner.drop.append(card)
            self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=card, source_zone="deck")
            removed += 1
        if removed:
            self._checkpoint(state, "effect_auto_place_top_n_from_owner_deck_into_drop")

    def _handle_auto_place_life_to_drop_and_deal_damage_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        life_to_drop_count = self._resolve_effect_int_param(state, reg, "life_to_drop_count", default=1)
        for damage_index in range(min(max(life_to_drop_count, 0), len(owner.life))):
            chosen_index = self._choose_life_card_index(owner, damage_index)
            chosen_index = max(0, min(chosen_index, len(owner.life) - 1))
            moved = owner.life.pop(chosen_index)
            owner.drop.append(moved)
            self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=moved, source_zone="life")
        damage_amount = self._resolve_effect_int_param(state, reg, "damage_amount", default=0)
        if damage_amount > 0:
            self._deal_damage_to_player(state, self._opponent_of(reg.owner_player_id), damage_amount)
        self._checkpoint(state, "effect_auto_place_life_to_drop_and_deal_damage_on_play")

    def _handle_auto_draw_n_discard_n(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        discard_amount = self._resolve_effect_int_param(state, reg, "discard_amount", default=amount)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        for _ in range(min(max(discard_amount, 0), len(owner.hand))):
            discarded = owner.hand.pop(0)
            owner.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=discarded, source_zone="hand")
        self._checkpoint(state, "effect_auto_draw_n_discard_n")

    def _handle_auto_send_up_to_n_opponent_combo_to_drop_on_opponent_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed":
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        if event.actor_player_id != opponent_id:
            return
        source_lookup = self._find_card_anywhere_by_instance(
            state,
            owner_player_id=opponent_id,
            instance_id=int(event.payload.get("source_instance_id") or -1),
        )
        if source_lookup is None:
            return
        _zone_name, combo_source = source_lookup
        if str(combo_source.card_type or "").strip().upper() not in {"BATTLE", "Z-BATTLE"}:
            return
        max_energy_cost = self._resolve_effect_int_param(state, reg, "max_energy_cost", default=-1)
        if max_energy_cost >= 0 and int(combo_source.energy_cost or 0) > max_energy_cost:
            return
        opponent = state.players.get(opponent_id)
        if opponent is None or not opponent.combo_area:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        indexes = self._choose_effect_target_indexes(state, reg, list(opponent.combo_area), max_targets, str(reg.handler_params.get("target_policy", "first")))
        if not indexes:
            return
        candidates = list(opponent.combo_area)
        selected_ids = {candidates[idx].instance_id for idx in indexes}
        i = 0
        while i < len(opponent.combo_area):
            combo_card = opponent.combo_area[i]
            if combo_card.instance_id not in selected_ids:
                i += 1
                continue
            moved = opponent.combo_area.pop(i)
            opponent.drop.append(moved)
            self._emit_card_placed_into_drop(state, owner_player_id=opponent_id, card=moved, source_zone="combo")
        self._checkpoint(state, "effect_auto_send_up_to_n_opponent_combo_to_drop_on_opponent_combo")

    def _handle_auto_pay_z_energy_bottom_deck_opponent_hand_on_opponent_combo_and_negate_self_for_battle(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed":
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        if event.actor_player_id != opponent_id:
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(opponent_id)
        if owner is None or opponent is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        if not self._can_pay_skill_cost(owner, source, "auto_on_opponent_combo", source_zone=reg.source_zone):
            return
        self._pay_skill_cost(state, owner, source, "auto_on_opponent_combo", source_zone=reg.source_zone)
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        moved = 0
        while moved < max(amount, 0) and opponent.hand:
            opponent.deck.append(int(opponent.hand.pop(0).card_id))
            moved += 1
        if bool(reg.handler_params.get("negate_self_skill_for_battle", False)):
            added = self._add_battle_skill_activation_restriction(
                state,
                owner_player_id=reg.owner_player_id,
                restricted_card_id=int(reg.source_card_id),
                scope="auto",
                trigger=str(reg.trigger),
                handler_id=str(reg.handler_id),
                handler_params_signature=self._handler_params_signature(reg.handler_params),
            )
            if added:
                self._checkpoint(state, "effect_battle_skill_activation_restriction_applied")
        self._checkpoint(state, "effect_auto_pay_z_energy_bottom_deck_opponent_hand_on_opponent_combo_and_negate_self_for_battle")

    def _handle_auto_opponent_bottom_decks_n_from_hand_on_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        required_comboed_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if required_comboed_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_comboed_from:
                return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None or not opponent.hand:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        moved = 0
        while moved < max(amount, 0) and opponent.hand:
            opponent.deck.append(int(opponent.hand.pop(0).card_id))
            moved += 1
        if moved > 0:
            self._checkpoint(state, "effect_auto_opponent_bottom_decks_n_from_hand_on_combo")

    def _handle_auto_switch_up_to_n_opponent_leader_or_battle_rest_on_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        required_comboed_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if required_comboed_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_comboed_from:
                return
        if not self._effect_requirements_met(state, reg):
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        policy = str(reg.handler_params.get("target_policy", "first") or "first")
        targets = [
            card
            for card in self._select_opponent_cards(
                state,
                owner_player_id=reg.owner_player_id,
                max_targets=max_targets,
                policy=policy,
            )
            if str(card.card_type or "").strip().upper() in {"LEADER", "BATTLE", "Z-BATTLE"}
        ]
        if not targets:
            return
        for target in targets:
            target.resting = True
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_leader_or_battle_rest_on_combo")

    def _handle_auto_send_owner_drop_to_warp_and_reduce_up_to_n_opponent_battle_for_turn_on_self_or_opponent_battle_played(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        amount = self._resolve_effect_int_param(state, reg, "cost_amount", default=1)
        required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("cost_required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        matching_drop_indexes = [
            i
            for i, card in enumerate(owner.drop)
            if self._card_matches_effect_filters(
                card,
                allowed_colors=set(),
                required_traits=required_traits,
                required_characters=set(),
                required_name_contains="",
            )
        ]
        if len(matching_drop_indexes) < amount:
            return
        removed = 0
        for idx in matching_drop_indexes[:amount]:
            moved = owner.drop.pop(idx - removed)
            removed += 1
            self._append_to_owner_warp(state, owner_player_id=reg.owner_player_id, card=moved, source_zone="drop")
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=-20000)
        for target in targets:
            self._apply_temporary_power_delta(
                state,
                card=target,
                delta=delta,
                reason="effect_auto_send_owner_drop_to_warp_and_reduce_up_to_n_opponent_battle_for_turn_on_self_or_opponent_battle_played",
            )
        self._checkpoint(state, "effect_auto_send_owner_drop_to_warp_and_reduce_up_to_n_opponent_battle_for_turn_on_self_or_opponent_battle_played")

    def _handle_auto_opponent_bottom_decks_from_hand_until_n_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        hand_limit = self._resolve_effect_int_param(state, reg, "hand_limit", default=10)
        min_opponent_hand = self._resolve_effect_int_param(state, reg, "min_opponent_hand", default=hand_limit + 1)
        if len(opponent.hand) < min_opponent_hand:
            return
        while len(opponent.hand) > hand_limit:
            moved = opponent.hand.pop(0)
            opponent.deck.append(moved.card_id)
        self._checkpoint(state, "effect_auto_opponent_bottom_decks_from_hand_until_n_on_play")

    def _handle_auto_negate_attack_on_opponent_attack(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        marker_delta = self._resolve_effect_int_param(state, reg, "marker_delta", default=0)
        if marker_delta < 0:
            needed = abs(marker_delta)
            if int(source.markers or 0) < needed:
                return
            self._remove_unison_markers(state, unison=source, amount=needed, reason="rule")
        state.counter_window = None
        state.attack_context = None
        state.battle_step = BattleStep.BATTLE_END
        self._checkpoint(state, "battle_end_step")
        self._checkpoint(state, "effect_auto_negate_attack_on_opponent_attack")

    def _handle_auto_add_top_deck_to_energy_rest_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.deck:
            return
        card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=owner.deck.pop(0), owner_id=reg.owner_player_id)
        state.next_instance_id += 1
        card.resting = True
        owner.energy.append(card)
        self._checkpoint(state, "effect_auto_add_top_deck_to_energy_rest_on_play")

    def _handle_auto_send_up_to_n_opponent_battle_to_warp_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        target_policy = str(reg.handler_params.get("target_policy", "first"))
        selected = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=max_targets,
            max_cost=max_cost,
            policy=target_policy,
        )
        if not selected:
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        opponent = state.players.get(opponent_id)
        if opponent is None:
            return
        target_ids = {c.instance_id for c in selected}
        i = 0
        while i < len(opponent.battle_area):
            card = opponent.battle_area[i]
            if card.instance_id not in target_ids:
                i += 1
                continue
            self._append_to_owner_warp(state, owner_player_id=opponent_id, card=opponent.battle_area.pop(i))
        self._checkpoint(state, "effect_auto_send_up_to_n_opponent_battle_to_warp_on_play")

    def _handle_auto_place_all_opponent_battles_up_to_cost_under_self_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        opponent = state.players.get(opponent_id)
        if opponent is None:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        kept: list[CardInstance] = []
        moved = 0
        for card in list(opponent.battle_area):
            if max_cost >= 0 and int(card.energy_cost or 0) > max_cost:
                kept.append(card)
                continue
            if self._card_currently_has_barrier(card):
                kept.append(card)
                continue
            self._place_card_under_host(source, card)
            moved += 1
        if moved <= 0:
            return
        opponent.battle_area = [card for card in opponent.battle_area if card in kept]
        self._checkpoint(state, "effect_auto_place_all_opponent_battles_up_to_cost_under_self_on_play")

    def _handle_auto_restrict_self_copies_from_hand_next_turn_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        restricted_card_id = int(reg.handler_params.get("restricted_card_id") or reg.source_card_id or -1)
        if restricted_card_id <= 0:
            return
        state.scheduled_card_play_restrictions.append(
            DelayedCardPlayRestriction(
                owner_player_id=reg.owner_player_id,
                restricted_card_id=restricted_card_id,
            )
        )
        self._checkpoint(state, "effect_auto_restrict_self_copies_from_hand_next_turn_on_play")

    def _handle_auto_remove_self_prevent_leader_damage_and_battle_ko_for_battle(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        ctx = state.attack_context
        owner = state.players.get(reg.owner_player_id)
        if ctx is None or owner is None:
            return
        if int(ctx.target_player_id) != int(reg.owner_player_id):
            return
        if ctx.target_zone not in {"leader", "battle"}:
            return
        target = self._find_by_instance(owner, ctx.target_zone, ctx.target_instance_id)
        if target is None:
            return
        if not self._card_matches_effect_filters(
            target,
            allowed_colors=set(),
            required_traits=set(),
            required_characters={"gogeta: gt"},
            required_name_contains="",
        ):
            return
        removed = False
        for zone_cards in (owner.battle_area, owner.unison_area):
            for idx, card in enumerate(zone_cards):
                if int(card.instance_id) != int(reg.source_instance_id):
                    continue
                owner.removed_from_game.append(zone_cards.pop(idx))
                removed = True
                break
            if removed:
                break
        if not removed:
            return
        state.battle_no_damage_player_ids.add(reg.owner_player_id)
        if ctx.target_zone == "battle":
            state.battle_ko_protected_instance_ids.add(ctx.target_instance_id)
        self._checkpoint(state, "effect_auto_remove_self_prevent_leader_damage_and_battle_ko_for_battle")

    def _handle_auto_apply_non_leader_attack_rest_tax_warp_self_and_optionally_negate_opponent_strike(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != int(reg.source_instance_id):
            return
        if str(event.payload.get("played_from") or "").strip().lower() != "hand":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        state.non_leader_attack_rest_taxes.append(
            NonLeaderAttackRestTax(
                owner_player_id=reg.owner_player_id,
                affected_player_id=self._opponent_of(reg.owner_player_id),
                rest_count=self._resolve_effect_int_param(state, reg, "rest_count", default=1),
                expires_on_turn_end_player_id=state.active_player,
            )
        )
        self._schedule_delayed_warp(
            state,
            owner_player_id=reg.owner_player_id,
            target_instance_id=reg.source_instance_id,
            trigger_player_id=state.active_player,
        )
        has_yellow_z_battle = any(
            str(card.card_type or "").strip().upper() == "Z-BATTLE"
            and "yellow" in str(card.color or "").strip().lower()
            for card in owner.battle_area
        )
        leader_is_z_leader = bool(getattr(owner.leader_area, "awakened", False)) or str(owner.leader_area.card_type or "").strip().upper().startswith("Z-")
        if leader_is_z_leader or has_yellow_z_battle:
            state.negate_opponent_strike_for_player_ids.add(reg.owner_player_id)
        self._checkpoint(state, "effect_auto_apply_non_leader_attack_rest_tax_warp_self_and_optionally_negate_opponent_strike")

    def _handle_auto_add_life_to_hand_and_buff_owner_leader_on_owner_matching_battle_played(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        played = self._find_board_card_by_instance(owner, int(event.payload.get("source_instance_id") or -1))
        if played is None:
            return
        played_colors = {
            part.strip().lower()
            for part in str(played.color or "").replace("/", ",").split(",")
            if part.strip()
        }
        if len(played_colors) < 2:
            return
        runtime = self._resolve_card_runtime_data(played.card_id)
        characters = {
            part.strip().lower()
            for part in [*tuple(runtime.characters or ()), *tuple(getattr(played, "characters", ()) or ())]
            if part.strip()
        }
        has_pan = "pan" in characters
        has_gt = any("gt" in part for part in characters)
        if not (has_pan or has_gt):
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        marker_delta = self._resolve_effect_int_param(state, reg, "marker_delta", default=0)
        if marker_delta > 0:
            source.markers += marker_delta
        if owner.life:
            owner.hand.append(owner.life.pop(0))
        self._apply_temporary_power_delta(state, card=owner.leader_area, delta=5000, reason="effect_owner_leader_buff_on_matching_battle_play")
        self._checkpoint(state, "effect_auto_add_life_to_hand_and_buff_owner_leader_on_owner_matching_battle_played")

    def _handle_auto_buff_played_battle_and_draw_if_power_at_least(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if str(event.payload.get("source_zone") or "").strip().lower() != "battle":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        target = self._find_by_instance(owner, "battle", int(event.payload.get("source_instance_id") or -1))
        if target is None:
            return
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        threshold = self._resolve_effect_int_param(state, reg, "draw_if_power_at_least", default=-1)
        before_power = int(target.power or 0)
        if delta:
            self._apply_temporary_power_delta(state, card=target, delta=delta, reason="effect_owner_battle_played_battle_buff")
        after_power = int(target.power or 0)
        if threshold >= 0 and before_power < threshold <= after_power and owner.deck:
            self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_buff_played_battle_and_draw_if_power_at_least")

    def _handle_auto_power_reduce_up_to_n_opponent_cards_for_turn_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if delta == 0:
            return
        target_scope = str(reg.handler_params.get("target_scope", "battle")).strip().lower()
        if target_scope in {"battle_or_unison", "board"}:
            candidates = [*opponent.battle_area, *opponent.unison_area]
            if not bool(reg.handler_params.get("ignores_barrier", False)):
                candidates = [card for card in candidates if not self._card_currently_has_barrier(card)]
            if not candidates:
                return
            indexes = self._choose_effect_target_indexes(
                state,
                reg,
                candidates,
                max_targets,
                str(reg.handler_params.get("target_policy", "first")),
            )
            targets = [candidates[idx] for idx in indexes]
        else:
            targets = self._select_opponent_battle_targets(
                state,
                reg,
                max_targets=max_targets,
                max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
                policy=str(reg.handler_params.get("target_policy", "first")),
            )
        if not targets:
            return
        for target in targets:
            self._apply_temporary_power_delta(
                state,
                card=target,
                delta=delta,
                reason="effect_auto_power_reduce_for_turn",
            )
        self._checkpoint(state, "effect_auto_power_reduce_up_to_n_opponent_cards_for_turn_on_play")

    def _handle_auto_switch_up_to_n_opponent_battle_rest_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        if not targets:
            return
        for target in targets:
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
            else:
                self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_battle_rest_on_play")

    def _handle_auto_switch_up_to_n_opponent_board_rest(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_played":
            if event.name != "card_played" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_attacks":
            if event.name != "attack_declared" or int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_added_to_z_energy":
            if event.name != "card_added_to_z_energy" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_placed_under_by_union":
            if event.name != "card_placed_under_card" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            if str(event.payload.get("placed_by") or "").strip().lower() != "union":
                return
        elif reg.trigger == "owner_card_placed_under_owner_card":
            if event.name != "card_placed_under_card":
                return
            if int(event.payload.get("host_owner_player_id") or -1) != reg.owner_player_id:
                return
            required_host_zone = str(reg.handler_params.get("required_host_zone", "")).strip().lower()
            host_zone = str(event.payload.get("host_zone") or "").strip().lower()
            if required_host_zone and host_zone != required_host_zone:
                return
            owner = state.players.get(reg.owner_player_id)
            if owner is None:
                return
            host_instance_id = int(event.payload.get("host_instance_id") or -1)
            host = self._find_by_instance(owner, host_zone, host_instance_id)
            if host is None:
                return
            host_name_contains = str(reg.handler_params.get("host_name_contains", "")).strip().upper()
            host_name = str(self._resolve_card_runtime_data(host.card_id).card_name or host.card_name or "").upper()
            if host_name_contains and host_name_contains not in host_name:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        targets = self._select_opponent_battle_or_unison_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
            prefer_attacker=bool(reg.handler_params.get("prefer_attacker", False)),
        )
        if not targets:
            return
        for target in targets:
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
            else:
                self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_board_rest")

    def _handle_auto_add_top_deck_to_energy_rest_and_bottom_deck_up_to_n_opponent_battle_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        if owner.deck:
            top_id = owner.deck.pop(0)
            energy_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=top_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            energy_card.resting = True
            owner.energy.append(energy_card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="energy", card=energy_card)
        selected = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        target_ids = {card.instance_id for card in selected}
        if target_ids:
            idx = 0
            while idx < len(opponent.battle_area):
                card = opponent.battle_area[idx]
                if card.instance_id not in target_ids:
                    idx += 1
                    continue
                opponent.deck.append(opponent.battle_area.pop(idx).card_id)
        self._checkpoint(state, "effect_auto_add_top_deck_to_energy_rest_and_bottom_deck_up_to_n_opponent_battle_on_play")

    def _handle_auto_negate_skills_and_restrict_up_to_n_opponent_battle_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if event.actor_player_id in {None, reg.owner_player_id}:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        marker_delta = self._resolve_effect_int_param(state, reg, "marker_delta", default=0)
        if marker_delta < 0 and source.card_type in {"UNISON", "Z-UNISON"} and source.markers < abs(marker_delta):
            return
        if marker_delta != 0 and source.card_type in {"UNISON", "Z-UNISON"}:
            source.markers += marker_delta
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        if not targets:
            return
        for target in targets:
            if self._opponent_skill_can_negate_battle_card_skills(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.temporary_skills_negated = True
            else:
                self._checkpoint(state, "counter_effect_attacker_skill_negation_prevented")
            state.attack_restricted_instance_ids.add(target.instance_id)
        self._checkpoint(state, "effect_auto_negate_skills_and_restrict_up_to_n_opponent_battle_on_attack")

    def _handle_auto_place_up_to_n_from_owner_drop_under_named_owner_battle_on_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed" or event.actor_player_id != reg.owner_player_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        combo_instance_id = int(event.payload.get("source_instance_id") or -1)
        combo_probe = next((card for card in owner.combo_area if card.instance_id == combo_instance_id), None)
        if combo_probe is None:
            combo_card_id = int(event.payload.get("source_card_id") or 0)
            combo_runtime = self._resolve_card_runtime_data(combo_card_id)
            combo_probe = CardInstance(
                instance_id=0,
                card_id=combo_card_id,
                owner_id=reg.owner_player_id,
                card_type=str(combo_runtime.card_type or "BATTLE"),
                color=str(combo_runtime.color or "") or None,
                traits=tuple(combo_runtime.traits or ()),
                characters=tuple(combo_runtime.characters or ()),
            )
        allowed_colors = {part.strip() for part in str(reg.handler_params.get("event_allowed_colors", "")).replace("|", ",").split(",") if part.strip()}
        required_traits = {part.strip() for part in str(reg.handler_params.get("event_required_traits", "")).replace("|", ",").split(",") if part.strip()}
        required_characters = {part.strip() for part in str(reg.handler_params.get("event_required_characters", "")).replace("|", ",").split(",") if part.strip()}
        required_name_contains = str(reg.handler_params.get("event_required_name_contains", "")).strip().upper()
        if not self._card_matches_effect_filters(
            combo_probe,
            allowed_colors=allowed_colors,
            required_traits=required_traits,
            required_characters=required_characters,
            required_name_contains=required_name_contains,
        ):
            return
        host_name = str(reg.handler_params.get("host_name_contains", "")).strip().upper()
        host = next(
            (
                card
                for card in owner.battle_area
                if host_name in str(self._resolve_card_runtime_data(card.card_id).card_name or "").upper()
            ),
            None,
        )
        if host is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        drop_candidates = [
            card
            for card in owner.drop
            if self._card_matches_effect_filters(
                card,
                allowed_colors={part.strip() for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").split(",") if part.strip()},
                required_traits={part.strip() for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",") if part.strip()},
                required_characters={part.strip() for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",") if part.strip()},
                required_name_contains=str(reg.handler_params.get("required_name_contains", "")).strip().upper(),
            )
        ]
        if not drop_candidates:
            return
        indexes = self._choose_effect_target_indexes(state, reg, drop_candidates, max_targets, str(reg.handler_params.get("target_policy", "first")))
        if not indexes:
            return
        selected_ids = {drop_candidates[idx].instance_id for idx in indexes}
        idx = 0
        while idx < len(owner.drop):
            card = owner.drop[idx]
            if card.instance_id not in selected_ids:
                idx += 1
                continue
            self._place_card_under_host(host, owner.drop.pop(idx))
        self._checkpoint(state, "effect_auto_place_up_to_n_from_owner_drop_under_named_owner_battle_on_combo")

    def _build_owner_combo_event_probe(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        event: EffectEvent,
    ) -> tuple[PlayerState, CardInstance | None, CardInstance] | None:
        owner = state.players.get(owner_player_id)
        if owner is None:
            return None
        combo_instance_id = int(event.payload.get("source_instance_id") or -1)
        live_combo_card = next((card for card in owner.combo_area if card.instance_id == combo_instance_id), None)
        if live_combo_card is not None:
            return owner, live_combo_card, live_combo_card
        combo_card_id = int(event.payload.get("source_card_id") or 0)
        if combo_card_id <= 0:
            return None
        combo_runtime = self._resolve_card_runtime_data(combo_card_id)
        combo_probe = CardInstance(
            instance_id=combo_instance_id if combo_instance_id > 0 else 0,
            card_id=combo_card_id,
            owner_id=owner_player_id,
            card_type=str(combo_runtime.card_type or "BATTLE"),
            color=str(combo_runtime.color or "") or None,
            power=int(combo_runtime.power or 0),
            energy_cost=combo_runtime.energy_cost,
            skill_text_raw=str(combo_runtime.skill_text_raw or ""),
            traits=tuple(combo_runtime.traits or ()),
            characters=tuple(combo_runtime.characters or ()),
            keywords=tuple(combo_runtime.keywords or ()),
            has_counter=bool(combo_runtime.has_counter),
            has_activate_main=bool(combo_runtime.has_activate_main),
            has_activate_battle=bool(combo_runtime.has_activate_battle),
            has_auto=bool(combo_runtime.has_auto),
            has_permanent=bool(combo_runtime.has_permanent),
            has_draw=bool(combo_runtime.has_draw),
            has_barrier=bool(combo_runtime.has_barrier),
        )
        return owner, None, combo_probe

    def _card_is_skillless(self, card: CardInstance) -> bool:
        keywords = {str(k).strip().lower() for k in (card.keywords or ()) if str(k).strip()}
        if "skill-less" in keywords or "skill less" in keywords:
            return True
        runtime = self._resolve_card_runtime_data(card.card_id)
        runtime_keywords = {str(k).strip().lower() for k in (runtime.keywords or ()) if str(k).strip()}
        if "skill-less" in runtime_keywords or "skill less" in runtime_keywords:
            return True
        raw_skill_text = str(getattr(card, "skill_text_raw", "") or runtime.skill_text_raw or "").strip().lower()
        if raw_skill_text in {"", "-"}:
            return True
        return not any(
            (
                bool(runtime.has_counter),
                bool(runtime.has_activate_main),
                bool(runtime.has_activate_battle),
                bool(runtime.has_auto),
                bool(runtime.has_permanent),
                bool(runtime.has_draw),
                bool(runtime.has_awaken),
                bool(runtime.keywords),
            )
        )

    def _match_owner_combo_event(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> tuple[PlayerState, CardInstance | None, CardInstance] | None:
        if event.name != "card_comboed" or event.actor_player_id != reg.owner_player_id:
            return None
        match = self._build_owner_combo_event_probe(state, owner_player_id=reg.owner_player_id, event=event)
        if match is None:
            return None
        owner, live_combo_card, combo_probe = match
        required_from = str(reg.handler_params.get("event_requires_comboed_from", "")).strip().lower()
        if required_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_from:
                return None
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("event_required_name_contains", "")).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("event_required_card_type", "")).replace("|", ",").split(",")
            if part.strip()
        }
        if not self._card_matches_effect_filters(
            combo_probe,
            allowed_colors=allowed_colors,
            required_traits=required_traits,
            required_characters=required_characters,
            required_name_contains=required_name_contains,
            required_card_types=required_card_types,
        ):
            return None
        event_min_cost = self._resolve_effect_int_param(state, reg, "event_min_energy_cost", default=-1)
        event_max_cost = self._resolve_effect_int_param(state, reg, "event_max_energy_cost", default=-1)
        event_exact_cost = self._resolve_effect_int_param(state, reg, "event_exact_energy_cost", default=-1)
        combo_cost = int(combo_probe.energy_cost or -1)
        if event_exact_cost >= 0 and combo_cost != event_exact_cost:
            return None
        if event_min_cost >= 0 and combo_cost < event_min_cost:
            return None
        if event_max_cost >= 0 and combo_cost > event_max_cost:
            return None
        if bool(reg.handler_params.get("event_requires_skill_less", False)) and not self._card_is_skillless(combo_probe):
            return None
        return owner, live_combo_card, combo_probe

    def _pay_owner_combo_skill_cost_if_needed(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
        owner: PlayerState,
    ) -> bool:
        paid_keys_obj = event.payload.get("_paid_owner_combo_cost_keys")
        paid_keys = set(paid_keys_obj) if isinstance(paid_keys_obj, list) else set()
        paid_key = f"{reg.owner_player_id}:{reg.source_zone}:{reg.source_instance_id}:auto_on_owner_combo_battle"
        if paid_key in paid_keys:
            return True
        total_cost, specified_costs = self._auto_header_cost_spec(reg)
        if (total_cost > 0 or specified_costs) and not self._can_pay_energy_cost(owner, total_cost, specified_costs=specified_costs):
            return False
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        source_zone = reg.source_zone
        if source is None and str(reg.source_zone or "").strip().lower() == "leader_under":
            source = self._create_card_instance(next_instance_id=0, card_id=reg.source_card_id, owner_id=reg.owner_player_id)
            source_zone = None
        if source is None:
            return False
        if not self._can_pay_skill_cost(owner, source, "auto_on_owner_combo_battle", source_zone=source_zone):
            return False
        if total_cost > 0 or specified_costs:
            self._pay_energy_cost(owner, total_cost, specified_costs=specified_costs)
        self._pay_skill_cost(state, owner, source, "auto_on_owner_combo_battle", source_zone=source_zone)
        paid_keys.add(paid_key)
        event.payload["_paid_owner_combo_cost_keys"] = list(paid_keys)
        return True

